insert into public.interview_questions (id, set_id, position, round_number, max_score, prompt, guidance, keywords, rubric, grading_rubric, reference_answer)
values ('f5986dfb-f6d0-5c9e-a3d0-c66f160707f7', (select id from public.interview_sets where slug = 'r2w-business-analyst-20261019'), 1, 1, 30, 'Giới thiệu bản thân và lý do bạn muốn theo đuổi vị trí Business Analyst', '', '{}'::text[], '[{"id":"criterion_1","label":"Nền tảng chuyên môn liên quan","weight":12,"maxScore":12},{"id":"criterion_2","label":"Lý do chọn nghề đúng bản chất","weight":10,"maxScore":10},{"id":"criterion_3","label":"Từ vựng & Sự tự tin","weight":8,"maxScore":8}]'::jsonb, '[{"id":"criterion_1","label":"Nền tảng chuyên môn liên quan","description":"Tiêu chí 1- Nền tảng chuyên môn liên quan (12đ): Nêu cụ thể ngành học/dự án đã làm liên quan trực tiếp đến phân tích nghiệp vụ, không nói chung chung.","keywords":[],"weight":12,"maxScore":12,"skill":"Nền tảng chuyên môn liên quan"},{"id":"criterion_2","label":"Lý do chọn nghề đúng bản chất","description":"Tiêu chí 2 - Lý do chọn nghề đúng bản chất (10đ): Phải chỉ ra đúng đặc thù công việc Business Analyst là phân tích vấn đề kinh doanh và làm cầu nối với đội kỹ thuật, không phải lý do chung chung như “yêu thích công nghệ”.","keywords":[],"weight":10,"maxScore":10,"skill":"Lý do chọn nghề đúng bản chất"},{"id":"criterion_3","label":"Từ vựng & Sự tự tin","description":"Tiêu chí 3 - Từ vựng & Sự tự tin (8đ): Trình bày mạch lạc, có dùng một số thuật ngữ cơ bản (yêu cầu nghiệp vụ/requirement, stakeholder).","keywords":[],"weight":8,"maxScore":8,"skill":"Từ vựng & Sự tự tin"}]'::jsonb, 'Tiêu chí 1- Nền tảng chuyên môn liên quan (12đ): Nêu cụ thể ngành học/dự án đã làm liên quan trực tiếp đến phân tích nghiệp vụ, không nói chung chung.
Tiêu chí 2 - Lý do chọn nghề đúng bản chất (10đ): Phải chỉ ra đúng đặc thù công việc Business Analyst là phân tích vấn đề kinh doanh và làm cầu nối với đội kỹ thuật, không phải lý do chung chung như “yêu thích công nghệ”.
Tiêu chí 3 - Từ vựng & Sự tự tin (8đ): Trình bày mạch lạc, có dùng một số thuật ngữ cơ bản (yêu cầu nghiệp vụ/requirement, stakeholder).')
on conflict (set_id, position) do nothing;
insert into public.interview_questions (id, set_id, position, round_number, max_score, prompt, guidance, keywords, rubric, grading_rubric, reference_answer)
values ('21ed6727-c579-5768-9fe7-073d0ca55331', (select id from public.interview_sets where slug = 'r2w-business-analyst-20261019'), 2, 1, 35, 'Bạn hiểu vai trò của một Business Analyst trong dự án phần mềm là gì?', '', '{}'::text[], '[{"id":"criterion_1","label":"Xác định đúng vai trò cầu nối","weight":15,"maxScore":15},{"id":"criterion_2","label":"Liệt kê đủ đầu việc cốt lõi","weight":12,"maxScore":12},{"id":"criterion_3","label":"Từ vựng & Sự tự tin","weight":8,"maxScore":8}]'::jsonb, '[{"id":"criterion_1","label":"Xác định đúng vai trò cầu nối","description":"Tiêu chí 1 - Xác định đúng vai trò cầu nối (15đ): Nêu rõ Business Analyst là người trung gian giữa khách hàng/doanh nghiệp và đội phát triển, KHÔNG lẫn với Project Manager - Quản lý dự án (quản lý tiến độ, nguồn lực) hay Dev (viết code).","keywords":[],"weight":15,"maxScore":15,"skill":"Xác định đúng vai trò cầu nối"},{"id":"criterion_2","label":"Liệt kê đủ đầu việc cốt lõi","description":"Tiêu chí 2 - Liệt kê đủ đầu việc cốt lõi (12đ): Nêu tối thiểu 3/5 đầu việc: thu thập yêu cầu, phân tích nghiệp vụ, viết tài liệu đặc tả (BRD/SRS), kiểm soát phạm vi (scope), hỗ trợ nghiệm thu (UAT).","keywords":[],"weight":12,"maxScore":12,"skill":"Liệt kê đủ đầu việc cốt lõi"},{"id":"criterion_3","label":"Từ vựng & Sự tự tin","description":"Tiêu chí 3 -Từ vựng & Sự tự tin (8đ): Dùng đúng thuật ngữ: Requirement, Stakeholder, Scope, UAT, BRD/SRS.","keywords":[],"weight":8,"maxScore":8,"skill":"Từ vựng & Sự tự tin"}]'::jsonb, 'Tiêu chí 1 - Xác định đúng vai trò cầu nối (15đ): Nêu rõ Business Analyst là người trung gian giữa khách hàng/doanh nghiệp và đội phát triển, KHÔNG lẫn với Project Manager - Quản lý dự án (quản lý tiến độ, nguồn lực) hay Dev (viết code).
Tiêu chí 2 - Liệt kê đủ đầu việc cốt lõi (12đ): Nêu tối thiểu 3/5 đầu việc: thu thập yêu cầu, phân tích nghiệp vụ, viết tài liệu đặc tả (BRD/SRS), kiểm soát phạm vi (scope), hỗ trợ nghiệm thu (UAT).
Tiêu chí 3 -Từ vựng & Sự tự tin (8đ): Dùng đúng thuật ngữ: Requirement, Stakeholder, Scope, UAT, BRD/SRS.')
on conflict (set_id, position) do nothing;
insert into public.interview_questions (id, set_id, position, round_number, max_score, prompt, guidance, keywords, rubric, grading_rubric, reference_answer)
values ('e31aa705-df43-5d32-98c1-7d413edbc900', (select id from public.interview_sets where slug = 'r2w-business-analyst-20261019'), 3, 1, 35, 'Bạn đã từng tham gia dự án/bài tập nào liên quan đến phân tích nghiệp vụ chưa?', '', '{}'::text[], '[{"id":"criterion_1","label":"Ví dụ dự án cụ thể","weight":15,"maxScore":15},{"id":"criterion_2","label":"Trình bày có ý theo cấu trúc STAR","weight":12,"maxScore":12},{"id":"criterion_3","label":"Rút ra bài học cụ thể","weight":8,"maxScore":8}]'::jsonb, '[{"id":"criterion_1","label":"Ví dụ dự án cụ thể","description":"Tiêu chí 1 - Ví dụ dự án cụ thể (15đ): Không trả lời “chưa có kinh nghiệm” chung chung - phải nêu tên/bối cảnh dự án hoặc bài tập cụ thể, vai trò đảm nhận rõ ràng.","keywords":[],"weight":15,"maxScore":15,"skill":"Ví dụ dự án cụ thể"},{"id":"criterion_2","label":"Trình bày có ý theo cấu trúc STAR","description":"Tiêu chí 2 - Trình bày có ý theo cấu trúc STAR (12đ): Bối cảnh (Situation) → Nhiệm vụ (Task) → Hành động cụ thể (Action) → Kết quả đo lường được (Result).","keywords":[],"weight":12,"maxScore":12,"skill":"Trình bày có ý theo cấu trúc STAR"},{"id":"criterion_3","label":"Rút ra bài học cụ thể","description":"Tiêu chí 3 - Rút ra bài học cụ thể (8đ): Chỉ ra được 1 bài học nghiệp vụ cụ thể, ví dụ: “phải xác nhận lại yêu cầu bằng văn bản trước khi triển khai”.","keywords":[],"weight":8,"maxScore":8,"skill":"Rút ra bài học cụ thể"}]'::jsonb, 'Tiêu chí 1 - Ví dụ dự án cụ thể (15đ): Không trả lời “chưa có kinh nghiệm” chung chung - phải nêu tên/bối cảnh dự án hoặc bài tập cụ thể, vai trò đảm nhận rõ ràng.
Tiêu chí 2 - Trình bày có ý theo cấu trúc STAR (12đ): Bối cảnh (Situation) → Nhiệm vụ (Task) → Hành động cụ thể (Action) → Kết quả đo lường được (Result).
Tiêu chí 3 - Rút ra bài học cụ thể (8đ): Chỉ ra được 1 bài học nghiệp vụ cụ thể, ví dụ: “phải xác nhận lại yêu cầu bằng văn bản trước khi triển khai”.')
on conflict (set_id, position) do nothing;
insert into public.interview_questions (id, set_id, position, round_number, max_score, prompt, guidance, keywords, rubric, grading_rubric, reference_answer)
values ('8ce5c1d3-32c6-55fd-8e1a-7ed1646f2fe0', (select id from public.interview_sets where slug = 'r2w-business-analyst-20261019'), 4, 2, 35, 'Phân biệt yêu cầu chức năng (Functional) và phi chức năng (Non-functional), cho ví dụ', '', '{}'::text[], '[{"id":"criterion_1","label":"Định nghĩa đúng Functional Requirement","weight":15,"maxScore":15},{"id":"criterion_2","label":"Định nghĩa đúng Non-functional Requirement","weight":12,"maxScore":12},{"id":"criterion_3","label":"Từ vựng & Sự tự tin","weight":8,"maxScore":8}]'::jsonb, '[{"id":"criterion_1","label":"Định nghĩa đúng Functional Requirement","description":"Tiêu chí 1 - Định nghĩa đúng Functional Requirement (15đ): Là yêu cầu mô tả HỆ THỐNG LÀM GÌ (VD: “cho phép đăng nhập bằng email”), kèm ví dụ cụ thể không chung chung.","keywords":[],"weight":15,"maxScore":15,"skill":"Định nghĩa đúng Functional Requirement"},{"id":"criterion_2","label":"Định nghĩa đúng Non-functional Requirement","description":"Tiêu chí 2 - Định nghĩa đúng Non-functional Requirement (12đ): Là yêu cầu mô tả hệ thống VẬN HÀNH TỐT ĐẾN MỨC NÀO (hiệu năng, bảo mật, khả dụng), kèm ví dụ có số liệu cụ thể (VD: “xử lý 1.000 người dùng đồng thời”).","keywords":[],"weight":12,"maxScore":12,"skill":"Định nghĩa đúng Non-functional Requirement"},{"id":"criterion_3","label":"Từ vựng & Sự tự tin","description":"Tiêu chí 3 - Từ vựng & Sự tự tin (8đ): Dùng đúng các thuật ngữ Functional/Non-functional Requirement, Performance, Security, Availability.","keywords":[],"weight":8,"maxScore":8,"skill":"Từ vựng & Sự tự tin"}]'::jsonb, 'Tiêu chí 1 - Định nghĩa đúng Functional Requirement (15đ): Là yêu cầu mô tả HỆ THỐNG LÀM GÌ (VD: “cho phép đăng nhập bằng email”), kèm ví dụ cụ thể không chung chung.
Tiêu chí 2 - Định nghĩa đúng Non-functional Requirement (12đ): Là yêu cầu mô tả hệ thống VẬN HÀNH TỐT ĐẾN MỨC NÀO (hiệu năng, bảo mật, khả dụng), kèm ví dụ có số liệu cụ thể (VD: “xử lý 1.000 người dùng đồng thời”).
Tiêu chí 3 - Từ vựng & Sự tự tin (8đ): Dùng đúng các thuật ngữ Functional/Non-functional Requirement, Performance, Security, Availability.')
on conflict (set_id, position) do nothing;
insert into public.interview_questions (id, set_id, position, round_number, max_score, prompt, guidance, keywords, rubric, grading_rubric, reference_answer)
values ('8ee5f96a-51eb-5332-9d3f-7992aa1d1dfa', (select id from public.interview_sets where slug = 'r2w-business-analyst-20261019'), 5, 2, 30, 'Bạn sẽ dùng phương pháp nào để thu thập yêu cầu từ khách hàng (phỏng vấn, workshop, khảo sát...)?', '', '{}'::text[], '[{"id":"criterion_1","label":"Khi nào dùng Phỏng vấn 1-1","weight":15,"maxScore":15},{"id":"criterion_2","label":"Khi nào dùng Workshop","weight":12,"maxScore":12},{"id":"criterion_3","label":"Từ vựng & Sự tự tin","weight":8,"maxScore":8}]'::jsonb, '[{"id":"criterion_1","label":"Khi nào dùng Phỏng vấn 1-1","description":"Tiêu chí 1 - Khi nào dùng Phỏng vấn 1-1 (15đ): Dùng khi cần đào sâu nghiệp vụ với người có chuyên môn cao, hoặc chủ đề nhạy cảm cần trao đổi riêng.","keywords":[],"weight":15,"maxScore":15,"skill":"Khi nào dùng Phỏng vấn 1-1"},{"id":"criterion_2","label":"Khi nào dùng Workshop","description":"Tiêu chí 2 - Khi nào dùng Workshop (12đ): Dùng khi có nhiều stakeholder với quan điểm khác nhau cần thống nhất trong cùng buổi họp để tiết kiệm thời gian, tránh yêu cầu mâu thuẫn.","keywords":[],"weight":12,"maxScore":12,"skill":"Khi nào dùng Workshop"},{"id":"criterion_3","label":"Từ vựng & Sự tự tin","description":"Tiêu chí 3 - Từ vựng & Sự tự tin (8đ): Dùng đúng các thuật ngữ Stakeholder, Workshop, Elicitation (khai thác yêu cầu).","keywords":[],"weight":8,"maxScore":8,"skill":"Từ vựng & Sự tự tin"}]'::jsonb, 'Tiêu chí 1 - Khi nào dùng Phỏng vấn 1-1 (15đ): Dùng khi cần đào sâu nghiệp vụ với người có chuyên môn cao, hoặc chủ đề nhạy cảm cần trao đổi riêng.
Tiêu chí 2 - Khi nào dùng Workshop (12đ): Dùng khi có nhiều stakeholder với quan điểm khác nhau cần thống nhất trong cùng buổi họp để tiết kiệm thời gian, tránh yêu cầu mâu thuẫn.
Tiêu chí 3 - Từ vựng & Sự tự tin (8đ): Dùng đúng các thuật ngữ Stakeholder, Workshop, Elicitation (khai thác yêu cầu).')
on conflict (set_id, position) do nothing;
insert into public.interview_questions (id, set_id, position, round_number, max_score, prompt, guidance, keywords, rubric, grading_rubric, reference_answer)
values ('93a74b34-6d30-5587-9930-406dc7abff6b', (select id from public.interview_sets where slug = 'r2w-business-analyst-20261019'), 6, 2, 35, 'Trình bày các thành phần chính trong một tài liệu SRS/BRD', '', '{}'::text[], '[{"id":"criterion_1","label":"Liệt kê đủ thành phần cốt lõi","weight":18,"maxScore":18},{"id":"criterion_2","label":"Giải thích đúng vai trò Acceptance Criteria","weight":10,"maxScore":10},{"id":"criterion_3","label":"Từ vựng & Sự tự tin","weight":7,"maxScore":7}]'::jsonb, '[{"id":"criterion_1","label":"Liệt kê đủ thành phần cốt lõi","description":"Tiêu chí 1 - Liệt kê đủ thành phần cốt lõi (18đ): Nêu tối thiểu 4/5: mục tiêu & phạm vi, yêu cầu chức năng chi tiết, yêu cầu phi chức năng, ràng buộc/giả định, tiêu chí nghiệm thu (acceptance criteria).","keywords":[],"weight":18,"maxScore":18,"skill":"Liệt kê đủ thành phần cốt lõi"},{"id":"criterion_2","label":"Giải thích đúng vai trò Acceptance Criteria","description":"Tiêu chí 2 - Giải thích đúng vai trò Acceptance Criteria (10đ): Nêu được đây là căn cứ để xác nhận sản phẩm đạt yêu cầu trước khi khách hàng nghiệm thu, tránh tranh cãi sau này.","keywords":[],"weight":10,"maxScore":10,"skill":"Giải thích đúng vai trò Acceptance Criteria"},{"id":"criterion_3","label":"Từ vựng & Sự tự tin","description":"Tiêu chí 3 - Từ vựng & Sự tự tin (7đ): Dùng đúng các thuật ngữ SRS, BRD, Acceptance Criteria, Constraint.","keywords":[],"weight":7,"maxScore":7,"skill":"Từ vựng & Sự tự tin"}]'::jsonb, 'Tiêu chí 1 - Liệt kê đủ thành phần cốt lõi (18đ): Nêu tối thiểu 4/5: mục tiêu & phạm vi, yêu cầu chức năng chi tiết, yêu cầu phi chức năng, ràng buộc/giả định, tiêu chí nghiệm thu (acceptance criteria).
Tiêu chí 2 - Giải thích đúng vai trò Acceptance Criteria (10đ): Nêu được đây là căn cứ để xác nhận sản phẩm đạt yêu cầu trước khi khách hàng nghiệm thu, tránh tranh cãi sau này.
Tiêu chí 3 - Từ vựng & Sự tự tin (7đ): Dùng đúng các thuật ngữ SRS, BRD, Acceptance Criteria, Constraint.')
on conflict (set_id, position) do nothing;
insert into public.interview_questions (id, set_id, position, round_number, max_score, prompt, guidance, keywords, rubric, grading_rubric, reference_answer)
values ('9c0eb84a-26ea-5eb6-8c51-dda07f9a41b6', (select id from public.interview_sets where slug = 'r2w-business-analyst-20261019'), 7, 3, 50, 'Khách hàng liên tục thay đổi yêu cầu giữa dự án, bạn xử lý thế nào?', '', '{}'::text[], '[{"id":"criterion_1","label":"Đề xuất đúng quy trình Change Request","weight":20,"maxScore":20},{"id":"criterion_2","label":"Đánh giá tác động trước khi quyết định","weight":20,"maxScore":20},{"id":"criterion_3","label":"Từ vựng & Sự tự tin","weight":10,"maxScore":10}]'::jsonb, '[{"id":"criterion_1","label":"Đề xuất đúng quy trình Change Request","description":"Tiêu chí 1 - Đề xuất đúng quy trình Change Request (20đ): Không phản đối/chấp nhận cảm tính, mà đề xuất ghi nhận yêu cầu bằng văn bản qua quy trình Change Request chính thức.","keywords":[],"weight":20,"maxScore":20,"skill":"Đề xuất đúng quy trình Change Request"},{"id":"criterion_2","label":"Đánh giá tác động trước khi quyết định","description":"Tiêu chí 2 - Đánh giá tác động trước khi quyết định (20đ): Nêu được cần đánh giá impact lên phạm vi (scope), thời gian, chi phí trước khi chấp nhận, và trao đổi lại với các bên liên quan (Project Manager, Dev) chứ không tự ý quyết định một mình.","keywords":[],"weight":20,"maxScore":20,"skill":"Đánh giá tác động trước khi quyết định"},{"id":"criterion_3","label":"Từ vựng & Sự tự tin","description":"Tiêu chí 3 - Từ vựng & Sự tự tin (10đ): Dùng đúng các thuật ngữ Change Request, Scope Creep, Impact Analysis.","keywords":[],"weight":10,"maxScore":10,"skill":"Từ vựng & Sự tự tin"}]'::jsonb, 'Tiêu chí 1 - Đề xuất đúng quy trình Change Request (20đ): Không phản đối/chấp nhận cảm tính, mà đề xuất ghi nhận yêu cầu bằng văn bản qua quy trình Change Request chính thức.
Tiêu chí 2 - Đánh giá tác động trước khi quyết định (20đ): Nêu được cần đánh giá impact lên phạm vi (scope), thời gian, chi phí trước khi chấp nhận, và trao đổi lại với các bên liên quan (Project Manager, Dev) chứ không tự ý quyết định một mình.
Tiêu chí 3 - Từ vựng & Sự tự tin (10đ): Dùng đúng các thuật ngữ Change Request, Scope Creep, Impact Analysis.')
on conflict (set_id, position) do nothing;
insert into public.interview_questions (id, set_id, position, round_number, max_score, prompt, guidance, keywords, rubric, grading_rubric, reference_answer)
values ('bc180bc6-3560-58b5-8367-6d4c56258d9d', (select id from public.interview_sets where slug = 'r2w-business-analyst-20261019'), 8, 3, 50, 'Đội Dev và khách hàng bất đồng về một yêu cầu, là Business Analyst bạn sẽ làm gì?', '', '{}'::text[], '[{"id":"criterion_1","label":"Đóng vai trò trung gian dựa trên tài liệu gốc","weight":20,"maxScore":20},{"id":"criterion_2","label":"Đề xuất giải pháp cụ thể để thống nhất","weight":20,"maxScore":20},{"id":"criterion_3","label":"Từ vựng & Sự tự tin","weight":10,"maxScore":10}]'::jsonb, '[{"id":"criterion_1","label":"Đóng vai trò trung gian dựa trên tài liệu gốc","description":"Tiêu chí 1 - Đóng vai trò trung gian dựa trên tài liệu gốc (20đ): Đề xuất quay lại tài liệu yêu cầu đã được khách hàng ký duyệt để làm rõ ý định ban đầu, KHÔNG đứng hẳn về phía Dev hay khách hàng theo cảm tính.","keywords":[],"weight":20,"maxScore":20,"skill":"Đóng vai trò trung gian dựa trên tài liệu gốc"},{"id":"criterion_2","label":"Đề xuất giải pháp cụ thể để thống nhất","description":"Tiêu chí 2 - Đề xuất giải pháp cụ thể để thống nhất (20đ): Nêu hành động cụ thể như tổ chức họp ba bên, hoặc làm prototype/wireframe để minh hoạ trực quan giúp cả hai bên cùng hình dung.","keywords":[],"weight":20,"maxScore":20,"skill":"Đề xuất giải pháp cụ thể để thống nhất"},{"id":"criterion_3","label":"Từ vựng & Sự tự tin","description":"Tiêu chí 3 - Từ vựng & Sự tự tin (10đ): Dùng đúng các thuật ngữ Traceability, Prototype, Sign-off.","keywords":[],"weight":10,"maxScore":10,"skill":"Từ vựng & Sự tự tin"}]'::jsonb, 'Tiêu chí 1 - Đóng vai trò trung gian dựa trên tài liệu gốc (20đ): Đề xuất quay lại tài liệu yêu cầu đã được khách hàng ký duyệt để làm rõ ý định ban đầu, KHÔNG đứng hẳn về phía Dev hay khách hàng theo cảm tính.
Tiêu chí 2 - Đề xuất giải pháp cụ thể để thống nhất (20đ): Nêu hành động cụ thể như tổ chức họp ba bên, hoặc làm prototype/wireframe để minh hoạ trực quan giúp cả hai bên cùng hình dung.
Tiêu chí 3 - Từ vựng & Sự tự tin (10đ): Dùng đúng các thuật ngữ Traceability, Prototype, Sign-off.')
on conflict (set_id, position) do nothing;
insert into public.interview_questions (id, set_id, position, round_number, max_score, prompt, guidance, keywords, rubric, grading_rubric, reference_answer)
values ('d1012603-98ac-5752-82df-b7b49386bccd', (select id from public.interview_sets where slug = 'r2w-credit-analyst-20261019'), 1, 1, 30, 'Giới thiệu bản thân và lý do bạn muốn theo đuổi vị trí Credit Analyst', '', '{}'::text[], '[{"id":"criterion_1","label":"Nền tảng chuyên môn","weight":12,"maxScore":12},{"id":"criterion_2","label":"Lý do chọn nghề","weight":10,"maxScore":10},{"id":"criterion_3","label":"Từ vựng và sự tự tin","weight":8,"maxScore":8}]'::jsonb, '[{"id":"criterion_1","label":"Nền tảng chuyên môn","description":"Tiêu chí 1 (12đ) - Nền tảng chuyên môn: Nêu ngành học, dự án liên quan đến tài chính, ngân hàng hoặc phân tích số liệu.","keywords":[],"weight":12,"maxScore":12,"skill":"Nền tảng chuyên môn"},{"id":"criterion_2","label":"Lý do chọn nghề","description":"Tiêu chí 2 (10đ) - Lý do chọn nghề: Hiểu đúng vai trò Credit Analyst là phân tích khả năng trả nợ, sức khỏe tài chính và mức độ tín nhiệm của khách hàng.","keywords":[],"weight":10,"maxScore":10,"skill":"Lý do chọn nghề"},{"id":"criterion_3","label":"Từ vựng và sự tự tin","description":"Tiêu chí 3 (8đ) - Từ vựng và sự tự tin: Trình bày tự tin, sử dụng đúng thuật ngữ","keywords":[],"weight":8,"maxScore":8,"skill":"Từ vựng và sự tự tin"}]'::jsonb, 'Tiêu chí 1 (12đ) - Nền tảng chuyên môn: Nêu ngành học, dự án liên quan đến tài chính, ngân hàng hoặc phân tích số liệu.
Tiêu chí 2 (10đ) - Lý do chọn nghề: Hiểu đúng vai trò Credit Analyst là phân tích khả năng trả nợ, sức khỏe tài chính và mức độ tín nhiệm của khách hàng.
Tiêu chí 3 (8đ) - Từ vựng và sự tự tin: Trình bày tự tin, sử dụng đúng thuật ngữ')
on conflict (set_id, position) do nothing;
insert into public.interview_questions (id, set_id, position, round_number, max_score, prompt, guidance, keywords, rubric, grading_rubric, reference_answer)
values ('0c587454-16dc-5d32-86eb-0dfb6cfb3e33', (select id from public.interview_sets where slug = 'r2w-credit-analyst-20261019'), 2, 1, 35, 'Bạn hiểu vai trò của một Credit Analyst là gì?', '', '{}'::text[], '[{"id":"criterion_1","label":"Vai trò cầu nối","weight":15,"maxScore":15},{"id":"criterion_2","label":"Nghiệp vụ cốt lõi","weight":12,"maxScore":12},{"id":"criterion_3","label":"Từ vựng và sự tự tin","weight":8,"maxScore":8}]'::jsonb, '[{"id":"criterion_1","label":"Vai trò cầu nối","description":"Tiêu chí 1 (15đ) - Vai trò cầu nối: Hiểu Credit Analyst phân tích thông tin tài chính và phi tài chính để hỗ trợ quyết định cấp tín dụng.","keywords":[],"weight":15,"maxScore":15,"skill":"Vai trò cầu nối"},{"id":"criterion_2","label":"Nghiệp vụ cốt lõi","description":"Tiêu chí 2 (12đ) - Nghiệp vụ cốt lõi: Nêu ít nhất 3 nội dung: phân tích BCTC, đánh giá dòng tiền, lịch sử tín dụng, khả năng trả nợ và xác định rủi ro tín dụng.","keywords":[],"weight":12,"maxScore":12,"skill":"Nghiệp vụ cốt lõi"},{"id":"criterion_3","label":"Từ vựng và sự tự tin","description":"Tiêu chí 3 (8đ) - Từ vựng và sự tự tin: Trình bày tự tin, sử dụng đúng thuật ngữ","keywords":[],"weight":8,"maxScore":8,"skill":"Từ vựng và sự tự tin"}]'::jsonb, 'Tiêu chí 1 (15đ) - Vai trò cầu nối: Hiểu Credit Analyst phân tích thông tin tài chính và phi tài chính để hỗ trợ quyết định cấp tín dụng.
Tiêu chí 2 (12đ) - Nghiệp vụ cốt lõi: Nêu ít nhất 3 nội dung: phân tích BCTC, đánh giá dòng tiền, lịch sử tín dụng, khả năng trả nợ và xác định rủi ro tín dụng.
Tiêu chí 3 (8đ) - Từ vựng và sự tự tin: Trình bày tự tin, sử dụng đúng thuật ngữ')
on conflict (set_id, position) do nothing;
