values ('ab57aa52-03f5-552d-a192-139e6bf77ad9', (select id from public.interview_sets where slug = 'r2w-credit-analyst-20261019'), 3, 1, 35, 'Bạn đã từng tham gia dự án/bài tập nào liên quan đến phân tích tài chính chưa?', '', '{}'::text[], '[{"id":"criterion_1","label":"Dự án cụ thể","weight":15,"maxScore":15},{"id":"criterion_2","label":"Cấu trúc STAR","weight":15,"maxScore":15},{"id":"criterion_3","label":"Bài học kinh nghiệm","weight":5,"maxScore":5}]'::jsonb, '[{"id":"criterion_1","label":"Dự án cụ thể","description":"Tiêu chí 1 (15đ) - Dự án cụ thể: Nêu tên dự án/bài tập và vai trò đảm nhận, không trả lời “chưa có kinh nghiệm”.","keywords":[],"weight":15,"maxScore":15,"skill":"Dự án cụ thể"},{"id":"criterion_2","label":"Cấu trúc STAR","description":"Tiêu chí 2 (15đ) - Cấu trúc STAR: (Situation), (Task), (Action), (Result).","keywords":[],"weight":15,"maxScore":15,"skill":"Cấu trúc STAR"},{"id":"criterion_3","label":"Bài học kinh nghiệm","description":"Tiêu chí 3 (5đ) - Bài học kinh nghiệm: Rút ra bài học nghiệp vụ cụ thể, ví dụ: xác nhận yêu cầu bằng văn bản trước khi triển khai.","keywords":[],"weight":5,"maxScore":5,"skill":"Bài học kinh nghiệm"}]'::jsonb, 'Tiêu chí 1 (15đ) - Dự án cụ thể: Nêu tên dự án/bài tập và vai trò đảm nhận, không trả lời “chưa có kinh nghiệm”.
Tiêu chí 2 (15đ) - Cấu trúc STAR: (Situation), (Task), (Action), (Result).
Tiêu chí 3 (5đ) - Bài học kinh nghiệm: Rút ra bài học nghiệp vụ cụ thể, ví dụ: xác nhận yêu cầu bằng văn bản trước khi triển khai.')
