values ('1cef7de9-6739-56f4-a526-bb66a1e9cc4b', (select id from public.interview_sets where slug = 'r2w-credit-analyst-20261019'), 5, 2, 35, 'Trình bày quy trình thẩm định tín dụng một khách hàng doanh nghiệp', '', '{}'::text[], '[{"id":"criterion_1","label":"Liệt kê đủ các bước","weight":15,"maxScore":15},{"id":"criterion_2","label":"Giải thích mục đích từng bước","weight":12,"maxScore":12},{"id":"criterion_3","label":"Từ vựng & Sự tự tin. Dùng đúng thuật ngữ","weight":8,"maxScore":8}]'::jsonb, '[{"id":"criterion_1","label":"Liệt kê đủ các bước","description":"Tiêu chí 1 (15đ)- Liệt kê đủ các bước:\n→  Thu thập hồ sơ\n→ Phân tích tài chính/phi tài chính\n→ Đánh giá tài sản bảo đảm\n→ Xếp hạng tín dụng\n→ Đề xuất cấp tín dụng\n→ Giám sát sau vay.","keywords":[],"weight":15,"maxScore":15,"skill":"Liệt kê đủ các bước"},{"id":"criterion_2","label":"Giải thích mục đích từng bước","description":"Tiêu chí 2 (12đ) - Giải thích mục đích từng bước","keywords":[],"weight":12,"maxScore":12,"skill":"Giải thích mục đích từng bước"},{"id":"criterion_3","label":"Từ vựng & Sự tự tin. Dùng đúng thuật ngữ","description":"Tiêu chí 3 (8đ) - Từ vựng & Sự tự tin. Dùng đúng thuật ngữ","keywords":[],"weight":8,"maxScore":8,"skill":"Từ vựng & Sự tự tin. Dùng đúng thuật ngữ"}]'::jsonb, 'Tiêu chí 1 (15đ)- Liệt kê đủ các bước:
→  Thu thập hồ sơ
→ Phân tích tài chính/phi tài chính
→ Đánh giá tài sản bảo đảm
→ Xếp hạng tín dụng
→ Đề xuất cấp tín dụng
→ Giám sát sau vay.
Tiêu chí 2 (12đ) - Giải thích mục đích từng bước
Tiêu chí 3 (8đ) - Từ vựng & Sự tự tin. Dùng đúng thuật ngữ')
on conflict (set_id, position) do nothing;
