values ('b95876a9-a59e-5623-81dd-a8465cb12e7f', (select id from public.interview_sets where slug = 'r2w-credit-analyst-20261019'), 6, 2, 35, 'Làm thế nào để đánh giá tài sản bảo đảm và tỷ lệ LTV (Loan-to-Value ratio) ?', '', '{}'::text[], '[{"id":"criterion_1","label":"Định nghĩa","weight":15,"maxScore":15},{"id":"criterion_2","label":"Quy trình đánh giá","weight":15,"maxScore":15},{"id":"criterion_3","label":"Từ vựng và sự tự tin","weight":5,"maxScore":5}]'::jsonb, '[{"id":"criterion_1","label":"Định nghĩa","description":"Tiêu chí 1 (15đ) - Định nghĩa: Hiểu đúng LTV là tỷ lệ dư nợ trên giá trị tài sản bảo đảm, ảnh hưởng đến hạn mức vay; nêu đúng khái niệm và vai trò của tài sản bảo đảm.","keywords":[],"weight":15,"maxScore":15,"skill":"Định nghĩa"},{"id":"criterion_2","label":"Quy trình đánh giá","description":"Tiêu chí 2 (15đ) - Quy trình đánh giá: Nêu đủ các bước: kiểm tra pháp lý, định giá độc lập và đánh giá tính thanh khoản của tài sản.","keywords":[],"weight":15,"maxScore":15,"skill":"Quy trình đánh giá"},{"id":"criterion_3","label":"Từ vựng và sự tự tin","description":"Tiêu chí 3 (5đ) - Từ vựng và sự tự tin: Trình bày tự tin, sử dụng đúng thuật ngữ","keywords":[],"weight":5,"maxScore":5,"skill":"Từ vựng và sự tự tin"}]'::jsonb, 'Tiêu chí 1 (15đ) - Định nghĩa: Hiểu đúng LTV là tỷ lệ dư nợ trên giá trị tài sản bảo đảm, ảnh hưởng đến hạn mức vay; nêu đúng khái niệm và vai trò của tài sản bảo đảm.
Tiêu chí 2 (15đ) - Quy trình đánh giá: Nêu đủ các bước: kiểm tra pháp lý, định giá độc lập và đánh giá tính thanh khoản của tài sản.
Tiêu chí 3 (5đ) - Từ vựng và sự tự tin: Trình bày tự tin, sử dụng đúng thuật ngữ')
on conflict (set_id, position) do nothing;
insert into public.interview_questions (id, set_id, position, round_number, max_score, prompt, guidance, keywords, rubric, grading_rubric, reference_answer)
values ('b9cfceb2-02a5-5ded-b3ff-3a6f295dfb22', (select id from public.interview_sets where slug = 'r2w-credit-analyst-20261019'), 7, 3, 50, 'Khách hàng có tài sản bảo đảm tốt nhưng dòng tiền yếu, bạn có đề xuất cho vay không?', '', '{}'::text[], '[{"id":"criterion_1","label":"Khả năng trả nợ","weight":20,"maxScore":20},{"id":"criterion_2","label":"Giảm thiểu rủi ro","weight":20,"maxScore":20},{"id":"criterion_3","label":"Từ vựng và sự tự tin","weight":10,"maxScore":10}]'::jsonb, '[{"id":"criterion_1","label":"Khả năng trả nợ","description":"Tiêu chí 1 (20đ) - Khả năng trả nợ: Phân tích dòng tiền và nguồn trả nợ của khách hàng, không chỉ dựa vào tài sản bảo đảm để quyết định cho vay.","keywords":[],"weight":20,"maxScore":20,"skill":"Khả năng trả nợ"},{"id":"criterion_2","label":"Giảm thiểu rủi ro","description":"Tiêu chí 2 (20đ) - Giảm thiểu rủi ro: Nêu ít nhất 3/4 phương án và giải thích tác dụng:\nGiảm hạn mức\nTăng tài sản bảo đảm\nThêm điều kiện covenant\nGiám sát chặt chẽ hơn.","keywords":[],"weight":20,"maxScore":20,"skill":"Giảm thiểu rủi ro"},{"id":"criterion_3","label":"Từ vựng và sự tự tin","description":"Tiêu chí 3 (10đ) - Từ vựng và sự tự tin: Trình bày tự tin, sử dụng đúng thuật ngữ","keywords":[],"weight":10,"maxScore":10,"skill":"Từ vựng và sự tự tin"}]'::jsonb, 'Tiêu chí 1 (20đ) - Khả năng trả nợ: Phân tích dòng tiền và nguồn trả nợ của khách hàng, không chỉ dựa vào tài sản bảo đảm để quyết định cho vay.
Tiêu chí 2 (20đ) - Giảm thiểu rủi ro: Nêu ít nhất 3/4 phương án và giải thích tác dụng:
Giảm hạn mức
Tăng tài sản bảo đảm
Thêm điều kiện covenant
Giám sát chặt chẽ hơn.
Tiêu chí 3 (10đ) - Từ vựng và sự tự tin: Trình bày tự tin, sử dụng đúng thuật ngữ')
on conflict (set_id, position) do nothing;
