values ('bdd990eb-f361-59a8-8a23-3c13ed7fc9c2', (select id from public.interview_sets where slug = 'r2w-financial-analyst-20261019'), 5, 2, 30, 'Quy trình xây dựng một mô hình dự báo tài chính đơn giản gồm những bước nào?', '', '{}'::text[], '[{"id":"criterion_1","label":"Quy trình lập dự phóng","weight":20,"maxScore":20},{"id":"criterion_2","label":"Trình bày và thuật ngữ","weight":10,"maxScore":10}]'::jsonb, '[{"id":"criterion_1","label":"Quy trình lập dự phóng","description":"Tiêu chí 1 (20đ) - Quy trình lập dự phóng: Nêu đúng thứ tự 6 bước: xác định mục tiêu, thu thập dữ liệu lịch sử, đặt giả định, dự phóng doanh thu/chi phí, lập báo cáo dự phóng và kiểm tra độ nhạy.","keywords":[],"weight":20,"maxScore":20,"skill":"Quy trình lập dự phóng"},{"id":"criterion_2","label":"Trình bày và thuật ngữ","description":"Tiêu chí 2 (10đ) - Trình bày và thuật ngữ: Trình bày rõ ràng, đúng thứ tự; sử dụng chính xác các thuật ngữ","keywords":[],"weight":10,"maxScore":10,"skill":"Trình bày và thuật ngữ"}]'::jsonb, 'Tiêu chí 1 (20đ) - Quy trình lập dự phóng: Nêu đúng thứ tự 6 bước: xác định mục tiêu, thu thập dữ liệu lịch sử, đặt giả định, dự phóng doanh thu/chi phí, lập báo cáo dự phóng và kiểm tra độ nhạy.
Tiêu chí 2 (10đ) - Trình bày và thuật ngữ: Trình bày rõ ràng, đúng thứ tự; sử dụng chính xác các thuật ngữ')
on conflict (set_id, position) do nothing;
