values ('c26b3886-8408-5f66-92ae-f850bf04b989', (select id from public.interview_sets where slug = 'r2w-financial-analyst-20261019'), 6, 2, 40, 'Trình bày 3 báo cáo tài chính chính và mối liên hệ giữa chúng', '', '{}'::text[], '[{"id":"criterion_1","label":"Ba báo cáo tài chính","weight":15,"maxScore":15},{"id":"criterion_2","label":"Giải thích ít nhất 4 mối liên hệ","weight":20,"maxScore":20},{"id":"criterion_3","label":"Từ vựng và sự tự tin","weight":5,"maxScore":5}]'::jsonb, '[{"id":"criterion_1","label":"Ba báo cáo tài chính","description":"Tiêu chí 1 (15đ) - Ba báo cáo tài chính: Nêu đúng tên, bản chất và thành phần của bảng","keywords":[],"weight":15,"maxScore":15,"skill":"Ba báo cáo tài chính"},{"id":"criterion_2","label":"Giải thích ít nhất 4 mối liên hệ","description":"Tiêu chí 2 (20đ) -Giải thích ít nhất 4 mối liên hệ","keywords":[],"weight":20,"maxScore":20,"skill":"Giải thích ít nhất 4 mối liên hệ"},{"id":"criterion_3","label":"Từ vựng và sự tự tin","description":"Tiêu chí 3 (5đ) - Từ vựng và sự tự tin: Trình bày tự tin, sử dụng đúng thuật ngữ","keywords":[],"weight":5,"maxScore":5,"skill":"Từ vựng và sự tự tin"}]'::jsonb, 'Tiêu chí 1 (15đ) - Ba báo cáo tài chính: Nêu đúng tên, bản chất và thành phần của bảng
Tiêu chí 2 (20đ) -Giải thích ít nhất 4 mối liên hệ
Tiêu chí 3 (5đ) - Từ vựng và sự tự tin: Trình bày tự tin, sử dụng đúng thuật ngữ')
on conflict (set_id, position) do nothing;
