values ('ec22afef-971d-554d-b155-1c3abccdc2cb', (select id from public.interview_sets where slug = 'r2w-financial-analyst-20261019'), 7, 3, 50, 'Sếp yêu cầu báo cáo tài chính gấp nhưng số liệu từ các phòng ban không khớp, bạn xử lý thế nào?', '', '{}'::text[], '[{"id":"criterion_1","label":"Xác định nguyên nhân và đối chiếu","weight":25,"maxScore":25},{"id":"criterion_2","label":"Minh bạch","weight":10,"maxScore":10},{"id":"criterion_3","label":"Trung thực","weight":10,"maxScore":10},{"id":"criterion_4","label":"Từ vựng & Sự tự tin","weight":5,"maxScore":5}]'::jsonb, '[{"id":"criterion_1","label":"Xác định nguyên nhân và đối chiếu","description":"Tiêu chí 1 (25đ) - Xác định nguyên nhân và đối chiếu: Đánh giá mức độ trọng yếu; nêu ít nhất 3 nguyên nhân","keywords":[],"weight":25,"maxScore":25,"skill":"Xác định nguyên nhân và đối chiếu"},{"id":"criterion_2","label":"Minh bạch","description":"Tiêu chí 2 (10đ) - Minh bạch: Báo cáo cấp trên, đề xuất thời hạn xử lý và đánh dấu các số liệu chưa chắc chắn.","keywords":[],"weight":10,"maxScore":10,"skill":"Minh bạch"},{"id":"criterion_3","label":"Trung thực","description":"Tiêu chí 3 (10đ) - Trung thực: Không tự ý điều chỉnh số liệu","keywords":[],"weight":10,"maxScore":10,"skill":"Trung thực"},{"id":"criterion_4","label":"Từ vựng & Sự tự tin","description":"Tiêu chí 4 - Từ vựng & Sự tự tin (5đ): Dùng đúng thuật ngữ","keywords":[],"weight":5,"maxScore":5,"skill":"Từ vựng & Sự tự tin"}]'::jsonb, 'Tiêu chí 1 (25đ) - Xác định nguyên nhân và đối chiếu: Đánh giá mức độ trọng yếu; nêu ít nhất 3 nguyên nhân
Tiêu chí 2 (10đ) - Minh bạch: Báo cáo cấp trên, đề xuất thời hạn xử lý và đánh dấu các số liệu chưa chắc chắn.
Tiêu chí 3 (10đ) - Trung thực: Không tự ý điều chỉnh số liệu
Tiêu chí 4 - Từ vựng & Sự tự tin (5đ): Dùng đúng thuật ngữ')
on conflict (set_id, position) do nothing;
insert into public.interview_questions (id, set_id, position, round_number, max_score, prompt, guidance, keywords, rubric, grading_rubric, reference_answer)
values ('08fe4ca5-5d15-59d2-bb62-1d37cf96d057', (select id from public.interview_sets where slug = 'r2w-financial-analyst-20261019'), 8, 3, 50, 'Kết quả phân tích cho thấy dự án thua lỗ nhưng sếp muốn tiếp tục, bạn làm gì?', '', '{}'::text[], '[{"id":"criterion_1","label":"Kiểm chứng phân tích và tìm hiểu lý do của sếp","weight":20,"maxScore":20},{"id":"criterion_2","label":"Phân tích số liệu","weight":10,"maxScore":10},{"id":"criterion_3","label":"Phương án tiếp tục","weight":10,"maxScore":10},{"id":"criterion_4","label":"Từ vựng và sự tự tin","weight":10,"maxScore":10}]'::jsonb, '[{"id":"criterion_1","label":"Kiểm chứng phân tích và tìm hiểu lý do của sếp","description":"Tiêu chí 1(20đ) - Kiểm chứng phân tích và tìm hiểu lý do của sếp: Rà lại giả định, dữ liệu; hỏi để hiểu lý do của sếp","keywords":[],"weight":20,"maxScore":20,"skill":"Kiểm chứng phân tích và tìm hiểu lý do của sếp"},{"id":"criterion_2","label":"Phân tích số liệu","description":"Tiêu chí 2 (10đ) - Phân tích số liệu: Nêu mức lỗ, thời gian hoàn vốn, điều kiện để dự án có lãi.","keywords":[],"weight":10,"maxScore":10,"skill":"Phân tích số liệu"},{"id":"criterion_3","label":"Phương án tiếp tục","description":"Tiêu chí 3 (10đ) - Phương án tiếp tục: Đề xuất ít nhất 3 phương án kèm chỉ số cắt lỗ:","keywords":[],"weight":10,"maxScore":10,"skill":"Phương án tiếp tục"},{"id":"criterion_4","label":"Từ vựng và sự tự tin","description":"Tiêu chí 4 (10đ) - Từ vựng và sự tự tin: Trình bày tự tin, sử dụng đúng thuật ngữ","keywords":[],"weight":10,"maxScore":10,"skill":"Từ vựng và sự tự tin"}]'::jsonb, 'Tiêu chí 1(20đ) - Kiểm chứng phân tích và tìm hiểu lý do của sếp: Rà lại giả định, dữ liệu; hỏi để hiểu lý do của sếp
Tiêu chí 2 (10đ) - Phân tích số liệu: Nêu mức lỗ, thời gian hoàn vốn, điều kiện để dự án có lãi.
Tiêu chí 3 (10đ) - Phương án tiếp tục: Đề xuất ít nhất 3 phương án kèm chỉ số cắt lỗ:
Tiêu chí 4 (10đ) - Từ vựng và sự tự tin: Trình bày tự tin, sử dụng đúng thuật ngữ')
on conflict (set_id, position) do nothing;
insert into public.interview_questions (id, set_id, position, round_number, max_score, prompt, guidance, keywords, rubric, grading_rubric, reference_answer)
values ('2f1edfbe-5d8a-52ab-bb61-5e565b4a37db', (select id from public.interview_sets where slug = 'r2w-ke-toan-vien-20261019'), 1, 1, 30, 'Hãy giới thiệu ngắn gọn về bản thân và lý do bạn lựa chọn công việc kế toán?', '', '{}'::text[], '[{"id":"criterion_1","label":"Giới thiệu đúng thông tin cá nhân","weight":12,"maxScore":12},{"id":"criterion_2","label":"Lý do chọn nghề đúng bản chất","weight":10,"maxScore":10},{"id":"criterion_3","label":"Liên hệ điểm mạnh với công việc","weight":8,"maxScore":8}]'::jsonb, '[{"id":"criterion_1","label":"Giới thiệu đúng thông tin cá nhân","description":"Tiêu chí 1- Giới thiệu đúng thông tin cá nhân  (12đ): Nêu được ngành học, kinh nghiệm/thực tập hoặc hoạt động liên quan đến kế toán.","keywords":[],"weight":12,"maxScore":12,"skill":"Giới thiệu đúng thông tin cá nhân"},{"id":"criterion_2","label":"Lý do chọn nghề đúng bản chất","description":"Tiêu chí 2 - Lý do chọn nghề đúng bản chất (10đ): Nêu được lý do cụ thể như yêu thích số liệu, quan tâm đến tài chính - kế toán hoặc muốn phát triển chuyên môn.","keywords":[],"weight":10,"maxScore":10,"skill":"Lý do chọn nghề đúng bản chất"},{"id":"criterion_3","label":"Liên hệ điểm mạnh với công việc","description":"Tiêu chí 3 - Liên hệ điểm mạnh với công việc (8đ): Nêu tối thiểu 2 điểm mạnh phù hợp như cẩn thận, chính xác, trung thực, trách nhiệm và giải thích được sự phù hợp.","keywords":[],"weight":8,"maxScore":8,"skill":"Liên hệ điểm mạnh với công việc"}]'::jsonb, 'Tiêu chí 1- Giới thiệu đúng thông tin cá nhân  (12đ): Nêu được ngành học, kinh nghiệm/thực tập hoặc hoạt động liên quan đến kế toán.
Tiêu chí 2 - Lý do chọn nghề đúng bản chất (10đ): Nêu được lý do cụ thể như yêu thích số liệu, quan tâm đến tài chính - kế toán hoặc muốn phát triển chuyên môn.
Tiêu chí 3 - Liên hệ điểm mạnh với công việc (8đ): Nêu tối thiểu 2 điểm mạnh phù hợp như cẩn thận, chính xác, trung thực, trách nhiệm và giải thích được sự phù hợp.')
on conflict (set_id, position) do nothing;
insert into public.interview_questions (id, set_id, position, round_number, max_score, prompt, guidance, keywords, rubric, grading_rubric, reference_answer)
values ('ec146649-5dc0-594a-8827-4543b6f5107a', (select id from public.interview_sets where slug = 'r2w-ke-toan-vien-20261019'), 2, 1, 35, 'Theo bạn, một kế toán viên cần có những kỹ năng quan trọng nào?', '', '{}'::text[], '[{"id":"criterion_1","label":"Chính xác và cẩn thận","weight":15,"maxScore":15},{"id":"criterion_2","label":"Kiến thức chuyên môn","weight":12,"maxScore":12},{"id":"criterion_3","label":"Trung thực và trách nhiệm","weight":8,"maxScore":8}]'::jsonb, '[{"id":"criterion_1","label":"Chính xác và cẩn thận","description":"Tiêu chí 1 - Chính xác và cẩn thận (15đ): Hiểu rằng kế toán thường xuyên làm việc với số liệu, hóa đơn và chứng từ nên cần hạn chế sai sót.","keywords":[],"weight":15,"maxScore":15,"skill":"Chính xác và cẩn thận"},{"id":"criterion_2","label":"Kiến thức chuyên môn","description":"Tiêu chí 2 - Kiến thức chuyên môn (12đ): Đề cập được hạch toán, chứng từ, sổ sách, doanh thu - chi phí hoặc nghiệp vụ kế toán cơ bản.","keywords":[],"weight":12,"maxScore":12,"skill":"Kiến thức chuyên môn"},{"id":"criterion_3","label":"Trung thực và trách nhiệm","description":"Tiêu chí 3 - Trung thực và trách nhiệm (8đ): Hiểu trách nhiệm của kế toán đối với số liệu và không cố tình làm sai lệch thông tin.","keywords":[],"weight":8,"maxScore":8,"skill":"Trung thực và trách nhiệm"}]'::jsonb, 'Tiêu chí 1 - Chính xác và cẩn thận (15đ): Hiểu rằng kế toán thường xuyên làm việc với số liệu, hóa đơn và chứng từ nên cần hạn chế sai sót.
Tiêu chí 2 - Kiến thức chuyên môn (12đ): Đề cập được hạch toán, chứng từ, sổ sách, doanh thu - chi phí hoặc nghiệp vụ kế toán cơ bản.
Tiêu chí 3 - Trung thực và trách nhiệm (8đ): Hiểu trách nhiệm của kế toán đối với số liệu và không cố tình làm sai lệch thông tin.')
on conflict (set_id, position) do nothing;
insert into public.interview_questions (id, set_id, position, round_number, max_score, prompt, guidance, keywords, rubric, grading_rubric, reference_answer)
values ('75c61f71-80b8-57b9-b034-b1f7df876782', (select id from public.interview_sets where slug = 'r2w-ke-toan-vien-20261019'), 3, 1, 35, 'Theo bạn, công việc của một kế toán viên trong doanh nghiệp thường bao gồm những nhiệm vụ gì?', '', '{}'::text[], '[{"id":"criterion_1","label":"Kiểm tra chứng từ","weight":15,"maxScore":15},{"id":"criterion_2","label":"Hiểu việc nhập liệu và hạch toán các nghiệp vụ phát sinh.","weight":12,"maxScore":12},{"id":"criterion_3","label":"Đối chiếu số liệu","weight":8,"maxScore":8}]'::jsonb, '[{"id":"criterion_1","label":"Kiểm tra chứng từ","description":"Tiêu chí 1 - Kiểm tra chứng từ (15đ): Nêu được việc tiếp nhận, kiểm tra hóa đơn và chứng từ liên quan.","keywords":[],"weight":15,"maxScore":15,"skill":"Kiểm tra chứng từ"},{"id":"criterion_2","label":"Hiểu việc nhập liệu và hạch toán các nghiệp vụ phát sinh.","description":"Tiêu chí 2 - Hiểu việc nhập liệu và hạch toán các nghiệp vụ phát sinh. (12d)","keywords":[],"weight":12,"maxScore":12,"skill":"Hiểu việc nhập liệu và hạch toán các nghiệp vụ phát sinh."},{"id":"criterion_3","label":"Đối chiếu số liệu","description":"Tiêu chí 3 - Đối chiếu số liệu (8đ): Biết cần đối chiếu giữa chứng từ, sổ sách và các nguồn dữ liệu liên quan.","keywords":[],"weight":8,"maxScore":8,"skill":"Đối chiếu số liệu"}]'::jsonb, 'Tiêu chí 1 - Kiểm tra chứng từ (15đ): Nêu được việc tiếp nhận, kiểm tra hóa đơn và chứng từ liên quan.
Tiêu chí 2 - Hiểu việc nhập liệu và hạch toán các nghiệp vụ phát sinh. (12d)
Tiêu chí 3 - Đối chiếu số liệu (8đ): Biết cần đối chiếu giữa chứng từ, sổ sách và các nguồn dữ liệu liên quan.')
on conflict (set_id, position) do nothing;
insert into public.interview_questions (id, set_id, position, round_number, max_score, prompt, guidance, keywords, rubric, grading_rubric, reference_answer)
values ('48d7accd-3f57-5894-9eeb-4beeabf7dd20', (select id from public.interview_sets where slug = 'r2w-ke-toan-vien-20261019'), 4, 2, 35, 'Khi phát hiện số liệu trên hóa đơn và chứng từ không khớp, bạn sẽ xử lý như thế nào?', '', '{}'::text[], '[{"id":"criterion_1","label":"Kiểm tra và đối chiếu","weight":15,"maxScore":15},{"id":"criterion_2","label":"Xác định nguyên nhân","weight":12,"maxScore":12},{"id":"criterion_3","label":"Xử lý đúng quy trình","weight":8,"maxScore":8}]'::jsonb, '[{"id":"criterion_1","label":"Kiểm tra và đối chiếu","description":"Tiêu chí 1 - Kiểm tra và đối chiếu (15đ): Đối chiếu hóa đơn với hợp đồng, phiếu nhập/xuất, biên bản giao nhận hoặc chứng từ thanh toán.","keywords":[],"weight":15,"maxScore":15,"skill":"Kiểm tra và đối chiếu"},{"id":"criterion_2","label":"Xác định nguyên nhân","description":"Tiêu chí 2 - Xác định nguyên nhân (12đ): Xác định chênh lệch về số tiền, số lượng, thông tin, thời điểm hoặc chứng từ.","keywords":[],"weight":12,"maxScore":12,"skill":"Xác định nguyên nhân"},{"id":"criterion_3","label":"Xử lý đúng quy trình","description":"Tiêu chí 3 - Xử lý đúng quy trình (8đ): Điều chỉnh/bổ sung chứng từ theo quy định trước khi ghi nhận chính thức.","keywords":[],"weight":8,"maxScore":8,"skill":"Xử lý đúng quy trình"}]'::jsonb, 'Tiêu chí 1 - Kiểm tra và đối chiếu (15đ): Đối chiếu hóa đơn với hợp đồng, phiếu nhập/xuất, biên bản giao nhận hoặc chứng từ thanh toán.
Tiêu chí 2 - Xác định nguyên nhân (12đ): Xác định chênh lệch về số tiền, số lượng, thông tin, thời điểm hoặc chứng từ.
Tiêu chí 3 - Xử lý đúng quy trình (8đ): Điều chỉnh/bổ sung chứng từ theo quy định trước khi ghi nhận chính thức.')
