insert into public.interview_questions (id, set_id, position, round_number, max_score, prompt, guidance, keywords, rubric, grading_rubric, reference_answer)
values ('a13ad6dd-95da-57c2-b729-cb665b9bd6cf', (select id from public.interview_sets where slug = 'r2w-ke-toan-vien-20261019'), 5, 2, 30, 'Hãy phân biệt doanh thu, chi phí và lợi nhuận trong hoạt động của doanh nghiệp.', '', '{}'::text[], '[{"id":"criterion_1","label":"Hiểu doanh thu","weight":10,"maxScore":10},{"id":"criterion_2","label":"Hiểu chi phí","weight":12,"maxScore":12},{"id":"criterion_3","label":"Hiểu lợi nhuận","weight":8,"maxScore":8}]'::jsonb, '[{"id":"criterion_1","label":"Hiểu doanh thu","description":"Tiêu chí 1 - Hiểu doanh thu (10đ): Giải thích đúng bản chất doanh thu từ hoạt động kinh doanh.","keywords":[],"weight":10,"maxScore":10,"skill":"Hiểu doanh thu"},{"id":"criterion_2","label":"Hiểu chi phí","description":"Tiêu chí 2 - Hiểu chi phí (12đ): Nêu được chi phí là các khoản phát sinh liên quan đến hoạt động tạo doanh thu.","keywords":[],"weight":12,"maxScore":12,"skill":"Hiểu chi phí"},{"id":"criterion_3","label":"Hiểu lợi nhuận","description":"Tiêu chí 3 - Hiểu lợi nhuận (8đ): Hiểu lợi nhuận được xác định dựa trên doanh thu và chi phí.","keywords":[],"weight":8,"maxScore":8,"skill":"Hiểu lợi nhuận"}]'::jsonb, 'Tiêu chí 1 - Hiểu doanh thu (10đ): Giải thích đúng bản chất doanh thu từ hoạt động kinh doanh.
Tiêu chí 2 - Hiểu chi phí (12đ): Nêu được chi phí là các khoản phát sinh liên quan đến hoạt động tạo doanh thu.
Tiêu chí 3 - Hiểu lợi nhuận (8đ): Hiểu lợi nhuận được xác định dựa trên doanh thu và chi phí.')
on conflict (set_id, position) do nothing;
insert into public.interview_questions (id, set_id, position, round_number, max_score, prompt, guidance, keywords, rubric, grading_rubric, reference_answer)
values ('506ec5fc-19b6-56fd-91a8-66550c11041a', (select id from public.interview_sets where slug = 'r2w-ke-toan-vien-20261019'), 6, 2, 35, 'Bạn sẽ làm gì nếu phát hiện một nghiệp vụ đã được ghi nhận sai?', '', '{}'::text[], '[{"id":"criterion_1","label":"Xác định sai sót","weight":18,"maxScore":18},{"id":"criterion_2","label":"Đánh giá ảnh hưởng","weight":7,"maxScore":7},{"id":"criterion_3","label":"Điều chỉnh đúng quy trình","weight":10,"maxScore":10}]'::jsonb, '[{"id":"criterion_1","label":"Xác định sai sót","description":"Tiêu chí 1 - Xác định sai sót (18đ): Kiểm tra sai tài khoản, số tiền, thời điểm hoặc nội dung nghiệp vụ.","keywords":[],"weight":18,"maxScore":18,"skill":"Xác định sai sót"},{"id":"criterion_2","label":"Đánh giá ảnh hưởng","description":"Tiêu chí 2 - Đánh giá ảnh hưởng (7đ): Xem xét ảnh hưởng đến tài khoản, doanh thu/chi phí, thuế hoặc báo cáo.","keywords":[],"weight":7,"maxScore":7,"skill":"Đánh giá ảnh hưởng"},{"id":"criterion_3","label":"Điều chỉnh đúng quy trình","description":"Tiêu chí 3 - Điều chỉnh đúng quy trình  (10đ): Thực hiện bút toán điều chỉnh hoặc xử lý chứng từ theo quy định.","keywords":[],"weight":10,"maxScore":10,"skill":"Điều chỉnh đúng quy trình"}]'::jsonb, 'Tiêu chí 1 - Xác định sai sót (18đ): Kiểm tra sai tài khoản, số tiền, thời điểm hoặc nội dung nghiệp vụ.
Tiêu chí 2 - Đánh giá ảnh hưởng (7đ): Xem xét ảnh hưởng đến tài khoản, doanh thu/chi phí, thuế hoặc báo cáo.
Tiêu chí 3 - Điều chỉnh đúng quy trình  (10đ): Thực hiện bút toán điều chỉnh hoặc xử lý chứng từ theo quy định.')
on conflict (set_id, position) do nothing;
insert into public.interview_questions (id, set_id, position, round_number, max_score, prompt, guidance, keywords, rubric, grading_rubric, reference_answer)
values ('6a63b8bf-d986-5335-a3ac-4ab9179e0f2c', (select id from public.interview_sets where slug = 'r2w-ke-toan-vien-20261019'), 7, 3, 50, 'Cuối ngày, bạn phát hiện một chứng từ quan trọng có sai sót nhưng quản lý đang yêu cầu hoàn thành báo cáo gấp. Bạn sẽ xử lý như thế nào?', '', '{}'::text[], '[{"id":"criterion_1","label":"Trung thực, không che giấu","weight":20,"maxScore":20},{"id":"criterion_2","label":"Đánh giá mức độ ảnh hưởng","weight":20,"maxScore":20},{"id":"criterion_3","label":"Ưu tiên công việc","weight":10,"maxScore":10}]'::jsonb, '[{"id":"criterion_1","label":"Trung thực, không che giấu","description":"Tiêu chí 1 - Trung thực, không che giấu (20đ): Thông báo về sai sót, không bỏ qua hoặc cố tình sửa số liệu.","keywords":[],"weight":20,"maxScore":20,"skill":"Trung thực, không che giấu"},{"id":"criterion_2","label":"Đánh giá mức độ ảnh hưởng","description":"Tiêu chí 2 - Đánh giá mức độ ảnh hưởng (20đ): Xác định chứng từ ảnh hưởng đến phần nào của báo cáo.","keywords":[],"weight":20,"maxScore":20,"skill":"Đánh giá mức độ ảnh hưởng"},{"id":"criterion_3","label":"Ưu tiên công việc","description":"Tiêu chí 3 - Ưu tiên công việc (10đ): Có thể hoàn thành phần báo cáo không bị ảnh hưởng trong khi xử lý sai sót.","keywords":[],"weight":10,"maxScore":10,"skill":"Ưu tiên công việc"}]'::jsonb, 'Tiêu chí 1 - Trung thực, không che giấu (20đ): Thông báo về sai sót, không bỏ qua hoặc cố tình sửa số liệu.
Tiêu chí 2 - Đánh giá mức độ ảnh hưởng (20đ): Xác định chứng từ ảnh hưởng đến phần nào của báo cáo.
Tiêu chí 3 - Ưu tiên công việc (10đ): Có thể hoàn thành phần báo cáo không bị ảnh hưởng trong khi xử lý sai sót.')
on conflict (set_id, position) do nothing;
insert into public.interview_questions (id, set_id, position, round_number, max_score, prompt, guidance, keywords, rubric, grading_rubric, reference_answer)
values ('e3fd0ab7-6326-59d2-bf9e-a5882c8f8963', (select id from public.interview_sets where slug = 'r2w-ke-toan-vien-20261019'), 8, 3, 50, 'Nếu đồng nghiệp đề nghị bạn bỏ qua một sai sót nhỏ trong chứng từ để kịp thời hạn báo cáo, bạn sẽ làm gì?', '', '{}'::text[], '[{"id":"criterion_1","label":"Nhận diện rủi ro","weight":20,"maxScore":20},{"id":"criterion_2","label":"Trao đổi với đồng nghiệp","weight":20,"maxScore":20},{"id":"criterion_3","label":"Tính trung thực","weight":10,"maxScore":10}]'::jsonb, '[{"id":"criterion_1","label":"Nhận diện rủi ro","description":"Tiêu chí 1 - Nhận diện rủi ro (20đ): Hiểu rằng sai sót nhỏ vẫn có thể gây ảnh hưởng nếu không được xử lý.","keywords":[],"weight":20,"maxScore":20,"skill":"Nhận diện rủi ro"},{"id":"criterion_2","label":"Trao đổi với đồng nghiệp","description":"Tiêu chí 2 - Trao đổi với đồng nghiệp (20đ): Giải thích lý do cần xử lý thay vì bỏ qua","keywords":[],"weight":20,"maxScore":20,"skill":"Trao đổi với đồng nghiệp"},{"id":"criterion_3","label":"Tính trung thực","description":"Tiêu chí 3 - Tính trung thực (10đ): Đặt tính chính xác và trung thực của số liệu lên trên việc đối phó với deadline.","keywords":[],"weight":10,"maxScore":10,"skill":"Tính trung thực"}]'::jsonb, 'Tiêu chí 1 - Nhận diện rủi ro (20đ): Hiểu rằng sai sót nhỏ vẫn có thể gây ảnh hưởng nếu không được xử lý.
Tiêu chí 2 - Trao đổi với đồng nghiệp (20đ): Giải thích lý do cần xử lý thay vì bỏ qua
Tiêu chí 3 - Tính trung thực (10đ): Đặt tính chính xác và trung thực của số liệu lên trên việc đối phó với deadline.')
on conflict (set_id, position) do nothing;
insert into public.interview_questions (id, set_id, position, round_number, max_score, prompt, guidance, keywords, rubric, grading_rubric, reference_answer)
values ('cda1648c-f99c-57ba-a97a-42fa55014af6', (select id from public.interview_sets where slug = 'r2w-kiem-toan-vien-20261019'), 1, 1, 30, 'Hãy giới thiệu ngắn gọn về bản thân và lý do bạn lựa chọn công việc kiểm toán.', '', '{}'::text[], '[{"id":"criterion_1","label":"Giới thiệu bản thân","weight":12,"maxScore":12},{"id":"criterion_2","label":"Lý do đúng bản chất nghề","weight":10,"maxScore":10},{"id":"criterion_3","label":"Hiểu công việc kiểm toán","weight":8,"maxScore":8}]'::jsonb, '[{"id":"criterion_1","label":"Giới thiệu bản thân","description":"Tiêu chí 1 - Giới thiệu bản thân (12đ): Nêu được ngành học, thực tập hoặc kinh nghiệm liên quan.","keywords":[],"weight":12,"maxScore":12,"skill":"Giới thiệu bản thân"},{"id":"criterion_2","label":"Lý do đúng bản chất nghề","description":"Tiêu chí 2 - Lý do đúng bản chất nghề (10đ): Nêu lý do cụ thể như yêu thích phân tích, kiểm tra số liệu, tìm hiểu hoạt động doanh nghiệp.","keywords":[],"weight":10,"maxScore":10,"skill":"Lý do đúng bản chất nghề"},{"id":"criterion_3","label":"Hiểu công việc kiểm toán","description":"Tiêu chí 3 - Hiểu công việc kiểm toán (8đ): Hiểu kiểm toán liên quan đến việc thu thập bằng chứng và đánh giá thông tin tài chính.","keywords":[],"weight":8,"maxScore":8,"skill":"Hiểu công việc kiểm toán"}]'::jsonb, 'Tiêu chí 1 - Giới thiệu bản thân (12đ): Nêu được ngành học, thực tập hoặc kinh nghiệm liên quan.
Tiêu chí 2 - Lý do đúng bản chất nghề (10đ): Nêu lý do cụ thể như yêu thích phân tích, kiểm tra số liệu, tìm hiểu hoạt động doanh nghiệp.
Tiêu chí 3 - Hiểu công việc kiểm toán (8đ): Hiểu kiểm toán liên quan đến việc thu thập bằng chứng và đánh giá thông tin tài chính.')
on conflict (set_id, position) do nothing;
insert into public.interview_questions (id, set_id, position, round_number, max_score, prompt, guidance, keywords, rubric, grading_rubric, reference_answer)
values ('7d2439b8-1ed9-5c81-bb94-a7a38d971e9c', (select id from public.interview_sets where slug = 'r2w-kiem-toan-vien-20261019'), 2, 1, 35, 'Theo bạn, một kiểm toán viên cần có những phẩm chất và kỹ năng nào?', '', '{}'::text[], '[{"id":"criterion_1","label":"Tư duy phân tích","weight":15,"maxScore":15},{"id":"criterion_2","label":"Khách quan và độc lập","weight":12,"maxScore":12},{"id":"criterion_3","label":"Cẩn thận","weight":8,"maxScore":8}]'::jsonb, '[{"id":"criterion_1","label":"Tư duy phân tích","description":"Tiêu chí 1 - Tư duy phân tích (15đ): Hiểu cần phân tích số liệu và tìm nguyên nhân của biến động.","keywords":[],"weight":15,"maxScore":15,"skill":"Tư duy phân tích"},{"id":"criterion_2","label":"Khách quan và độc lập","description":"Tiêu chí 2 - Khách quan và độc lập (12đ): Hiểu kiểm toán viên cần đưa ra đánh giá dựa trên bằng chứng, không thiên vị.","keywords":[],"weight":12,"maxScore":12,"skill":"Khách quan và độc lập"},{"id":"criterion_3","label":"Cẩn thận","description":"Tiêu chí 3 - Cẩn thận (8đ): Nhận thức được việc kiểm tra hồ sơ và bằng chứng cần chính xác.","keywords":[],"weight":8,"maxScore":8,"skill":"Cẩn thận"}]'::jsonb, 'Tiêu chí 1 - Tư duy phân tích (15đ): Hiểu cần phân tích số liệu và tìm nguyên nhân của biến động.
Tiêu chí 2 - Khách quan và độc lập (12đ): Hiểu kiểm toán viên cần đưa ra đánh giá dựa trên bằng chứng, không thiên vị.
Tiêu chí 3 - Cẩn thận (8đ): Nhận thức được việc kiểm tra hồ sơ và bằng chứng cần chính xác.')
on conflict (set_id, position) do nothing;
insert into public.interview_questions (id, set_id, position, round_number, max_score, prompt, guidance, keywords, rubric, grading_rubric, reference_answer)
values ('2433b0f5-3a66-5e52-b472-28662d2d9745', (select id from public.interview_sets where slug = 'r2w-kiem-toan-vien-20261019'), 3, 1, 35, 'Theo bạn, sự khác nhau cơ bản giữa kế toán và kiểm toán là gì?', '', '{}'::text[], '[{"id":"criterion_1","label":"Hiểu vai trò kế toán","weight":20,"maxScore":20},{"id":"criterion_2","label":"Hiểu vai trò kiểm toán","weight":10,"maxScore":10},{"id":"criterion_3","label":"Ví dụ minh họa","weight":5,"maxScore":5}]'::jsonb, '[{"id":"criterion_1","label":"Hiểu vai trò kế toán","description":"Tiêu chí 1 - Hiểu vai trò kế toán (20đ): Nêu đúng kế toán thực hiện ghi nhận và tổng hợp các nghiệp vụ.","keywords":[],"weight":20,"maxScore":20,"skill":"Hiểu vai trò kế toán"},{"id":"criterion_2","label":"Hiểu vai trò kiểm toán","description":"Tiêu chí 2 - Hiểu vai trò kiểm toán (10đ): Nêu đúng kiểm toán kiểm tra và đánh giá thông tin tài chính.","keywords":[],"weight":10,"maxScore":10,"skill":"Hiểu vai trò kiểm toán"},{"id":"criterion_3","label":"Ví dụ minh họa","description":"Tiêu chí 3 - Ví dụ minh họa (5đ): Có thể đưa ra ví dụ thực tế để phân biệt.","keywords":[],"weight":5,"maxScore":5,"skill":"Ví dụ minh họa"}]'::jsonb, 'Tiêu chí 1 - Hiểu vai trò kế toán (20đ): Nêu đúng kế toán thực hiện ghi nhận và tổng hợp các nghiệp vụ.
Tiêu chí 2 - Hiểu vai trò kiểm toán (10đ): Nêu đúng kiểm toán kiểm tra và đánh giá thông tin tài chính.
Tiêu chí 3 - Ví dụ minh họa (5đ): Có thể đưa ra ví dụ thực tế để phân biệt.')
on conflict (set_id, position) do nothing;
insert into public.interview_questions (id, set_id, position, round_number, max_score, prompt, guidance, keywords, rubric, grading_rubric, reference_answer)
values ('15f7705b-dd21-5b9a-b043-fcd0ac12ab20', (select id from public.interview_sets where slug = 'r2w-kiem-toan-vien-20261019'), 4, 2, 35, 'Theo bạn, mục tiêu chính của một cuộc kiểm toán báo cáo tài chính là gì?', '', '{}'::text[], '[{"id":"criterion_1","label":"Xác định đúng mục tiêu","weight":18,"maxScore":18},{"id":"criterion_2","label":"Sai sót trọng yếu","weight":10,"maxScore":10},{"id":"criterion_3","label":"Bằng chứng kiểm toán","weight":7,"maxScore":7}]'::jsonb, '[{"id":"criterion_1","label":"Xác định đúng mục tiêu","description":"Tiêu chí 1 - Xác định đúng mục tiêu (18đ): Nêu được mục tiêu đưa ra ý kiến về báo cáo tài chính dựa trên kết quả kiểm toán.","keywords":[],"weight":18,"maxScore":18,"skill":"Xác định đúng mục tiêu"},{"id":"criterion_2","label":"Sai sót trọng yếu","description":"Tiêu chí 2 - Sai sót trọng yếu (10đ): Hiểu kiểm toán tập trung vào những sai sót có thể ảnh hưởng đáng kể đến người sử dụng báo cáo.","keywords":[],"weight":10,"maxScore":10,"skill":"Sai sót trọng yếu"},{"id":"criterion_3","label":"Bằng chứng kiểm toán","description":"Tiêu chí 3 - Bằng chứng kiểm toán (7đ): Hiểu cần thu thập bằng chứng kiểm toán thích hợp.","keywords":[],"weight":7,"maxScore":7,"skill":"Bằng chứng kiểm toán"}]'::jsonb, 'Tiêu chí 1 - Xác định đúng mục tiêu (18đ): Nêu được mục tiêu đưa ra ý kiến về báo cáo tài chính dựa trên kết quả kiểm toán.
Tiêu chí 2 - Sai sót trọng yếu (10đ): Hiểu kiểm toán tập trung vào những sai sót có thể ảnh hưởng đáng kể đến người sử dụng báo cáo.
Tiêu chí 3 - Bằng chứng kiểm toán (7đ): Hiểu cần thu thập bằng chứng kiểm toán thích hợp.')
on conflict (set_id, position) do nothing;
insert into public.interview_questions (id, set_id, position, round_number, max_score, prompt, guidance, keywords, rubric, grading_rubric, reference_answer)
values ('334ecea7-35f5-5c5f-b432-50d97c5a98ab', (select id from public.interview_sets where slug = 'r2w-kiem-toan-vien-20261019'), 5, 2, 30, 'Nếu phát hiện một giao dịch có giá trị bất thường gần ngày kết thúc năm tài chính, bạn sẽ làm gì?', '', '{}'::text[], '[{"id":"criterion_1","label":"Nhận diện rủi ro","weight":15,"maxScore":15},{"id":"criterion_2","label":"Kiểm tra hồ sơ","weight":10,"maxScore":10},{"id":"criterion_3","label":"Kiểm tra thời điểm ghi nhận","weight":5,"maxScore":5}]'::jsonb, '[{"id":"criterion_1","label":"Nhận diện rủi ro","description":"Tiêu chí 1 - Nhận diện rủi ro (15đ): Nhận thấy giao dịch lớn và gần ngày khóa sổ có thể có rủi ro ghi nhận sai kỳ hoặc bất thường.","keywords":[],"weight":15,"maxScore":15,"skill":"Nhận diện rủi ro"},{"id":"criterion_2","label":"Kiểm tra hồ sơ","description":"Tiêu chí 2 - Kiểm tra hồ sơ (10đ): Kiểm tra hợp đồng, hóa đơn, phiếu xuất kho, biên bản giao nhận và thanh toán.","keywords":[],"weight":10,"maxScore":10,"skill":"Kiểm tra hồ sơ"},{"id":"criterion_3","label":"Kiểm tra thời điểm ghi nhận","description":"Tiêu chí 3 - Kiểm tra thời điểm ghi nhận  (5đ): Đối chiếu ngày giao hàng/chuyển giao với ngày ghi nhận doanh thu/chi phí.","keywords":[],"weight":5,"maxScore":5,"skill":"Kiểm tra thời điểm ghi nhận"}]'::jsonb, 'Tiêu chí 1 - Nhận diện rủi ro (15đ): Nhận thấy giao dịch lớn và gần ngày khóa sổ có thể có rủi ro ghi nhận sai kỳ hoặc bất thường.
Tiêu chí 2 - Kiểm tra hồ sơ (10đ): Kiểm tra hợp đồng, hóa đơn, phiếu xuất kho, biên bản giao nhận và thanh toán.
Tiêu chí 3 - Kiểm tra thời điểm ghi nhận  (5đ): Đối chiếu ngày giao hàng/chuyển giao với ngày ghi nhận doanh thu/chi phí.')
