insert into public.interview_questions (id, set_id, position, round_number, max_score, prompt, guidance, keywords, rubric, grading_rubric, reference_answer)
values ('1131f530-7d56-5ed3-8cc1-39026749f68f', (select id from public.interview_sets where slug = 'r2w-kiem-toan-vien-20261019'), 6, 2, 35, 'Bạn sẽ đánh giá rủi ro của một khoản mục như thế nào?', '', '{}'::text[], '[{"id":"criterion_1","label":"Tìm hiểu khoản mục","weight":20,"maxScore":20},{"id":"criterion_2","label":"Phân tích biến động và so sánh với kỳ trước, kế hoạch hoặc các khoản mục liên quan","weight":10,"maxScore":10},{"id":"criterion_3","label":"Xác định khả năng sai sót","weight":5,"maxScore":5}]'::jsonb, '[{"id":"criterion_1","label":"Tìm hiểu khoản mục","description":"Tiêu chí 1 - Tìm hiểu khoản mục (20đ): Hiểu bản chất và nguồn gốc phát sinh.","keywords":[],"weight":20,"maxScore":20,"skill":"Tìm hiểu khoản mục"},{"id":"criterion_2","label":"Phân tích biến động và so sánh với kỳ trước, kế hoạch hoặc các khoản mục liên quan","description":"Tiêu chí 2 - Phân tích biến động và so sánh với kỳ trước, kế hoạch hoặc các khoản mục liên quan (10đ): So sánh với kỳ trước, kế hoạch hoặc các khoản mục liên quan.","keywords":[],"weight":10,"maxScore":10,"skill":"Phân tích biến động và so sánh với kỳ trước, kế hoạch hoặc các khoản mục liên quan"},{"id":"criterion_3","label":"Xác định khả năng sai sót","description":"Tiêu chí 3 - Xác định khả năng sai sót (5đ): Xem xét ghi nhận sai, thiếu chứng từ, định giá sai hoặc gian lận.","keywords":[],"weight":5,"maxScore":5,"skill":"Xác định khả năng sai sót"}]'::jsonb, 'Tiêu chí 1 - Tìm hiểu khoản mục (20đ): Hiểu bản chất và nguồn gốc phát sinh.
Tiêu chí 2 - Phân tích biến động và so sánh với kỳ trước, kế hoạch hoặc các khoản mục liên quan (10đ): So sánh với kỳ trước, kế hoạch hoặc các khoản mục liên quan.
Tiêu chí 3 - Xác định khả năng sai sót (5đ): Xem xét ghi nhận sai, thiếu chứng từ, định giá sai hoặc gian lận.')
on conflict (set_id, position) do nothing;
insert into public.interview_questions (id, set_id, position, round_number, max_score, prompt, guidance, keywords, rubric, grading_rubric, reference_answer)
values ('84146489-765e-5492-bdab-206709c176c6', (select id from public.interview_sets where slug = 'r2w-kiem-toan-vien-20261019'), 7, 3, 50, 'Nếu khách hàng không cung cấp đầy đủ bằng chứng kiểm toán, bạn sẽ xử lý như thế nào?', '', '{}'::text[], '[{"id":"criterion_1","label":"Xác định bằng chứng thiếu","weight":20,"maxScore":20},{"id":"criterion_2","label":"Yêu cầu khách hàng bổ sung","weight":20,"maxScore":20},{"id":"criterion_3","label":"Tìm bằng chứng thay thế","weight":10,"maxScore":10}]'::jsonb, '[{"id":"criterion_1","label":"Xác định bằng chứng thiếu","description":"Tiêu chí 1 - Xác định bằng chứng thiếu (20đ): Xác định tài liệu nào chưa được cung cấp và liên quan khoản mục nào.","keywords":[],"weight":20,"maxScore":20,"skill":"Xác định bằng chứng thiếu"},{"id":"criterion_2","label":"Yêu cầu khách hàng bổ sung","description":"Tiêu chí 2 - Yêu cầu khách hàng bổ sung (20đ): Chủ động liên hệ và nêu rõ tài liệu cần cung cấp.","keywords":[],"weight":20,"maxScore":20,"skill":"Yêu cầu khách hàng bổ sung"},{"id":"criterion_3","label":"Tìm bằng chứng thay thế","description":"Tiêu chí 3 - Tìm bằng chứng thay thế (10đ): Có thể tìm xác nhận bên ngoài, chứng từ ngân hàng hoặc hồ sơ liên quan.","keywords":[],"weight":10,"maxScore":10,"skill":"Tìm bằng chứng thay thế"}]'::jsonb, 'Tiêu chí 1 - Xác định bằng chứng thiếu (20đ): Xác định tài liệu nào chưa được cung cấp và liên quan khoản mục nào.
Tiêu chí 2 - Yêu cầu khách hàng bổ sung (20đ): Chủ động liên hệ và nêu rõ tài liệu cần cung cấp.
Tiêu chí 3 - Tìm bằng chứng thay thế (10đ): Có thể tìm xác nhận bên ngoài, chứng từ ngân hàng hoặc hồ sơ liên quan.')
on conflict (set_id, position) do nothing;
insert into public.interview_questions (id, set_id, position, round_number, max_score, prompt, guidance, keywords, rubric, grading_rubric, reference_answer)
values ('f2bd17b0-838a-5e84-adb7-11e8f65984c6', (select id from public.interview_sets where slug = 'r2w-kiem-toan-vien-20261019'), 8, 3, 50, 'Khách hàng đưa ra lời giải thích nhưng bằng chứng không hoàn toàn phù hợp với lời giải thích đó. Bạn sẽ làm gì?', '', '{}'::text[], '[{"id":"criterion_1","label":"Không chấp nhận ngay lời giải thích","weight":20,"maxScore":20},{"id":"criterion_2","label":"Kiểm tra thêm bằng chứng","weight":20,"maxScore":20},{"id":"criterion_3","label":"Đánh giá rủi ro","weight":10,"maxScore":10}]'::jsonb, '[{"id":"criterion_1","label":"Không chấp nhận ngay lời giải thích","description":"Tiêu chí 1 - Không chấp nhận ngay lời giải thích (20đ): Hiểu rằng lời giải thích bằng miệng không thay thế hoàn toàn bằng chứng kiểm toán.","keywords":[],"weight":20,"maxScore":20,"skill":"Không chấp nhận ngay lời giải thích"},{"id":"criterion_2","label":"Kiểm tra thêm bằng chứng","description":"Tiêu chí 2 - Kiểm tra thêm bằng chứng (20đ): Đối chiếu hợp đồng, hóa đơn, thanh toán, giao nhận hoặc nguồn độc lập","keywords":[],"weight":20,"maxScore":20,"skill":"Kiểm tra thêm bằng chứng"},{"id":"criterion_3","label":"Đánh giá rủi ro","description":"Tiêu chí 3 - Đánh giá rủi ro (10đ): Xem xét có dấu hiệu sai sót hoặc gian lận hay không.","keywords":[],"weight":10,"maxScore":10,"skill":"Đánh giá rủi ro"}]'::jsonb, 'Tiêu chí 1 - Không chấp nhận ngay lời giải thích (20đ): Hiểu rằng lời giải thích bằng miệng không thay thế hoàn toàn bằng chứng kiểm toán.
Tiêu chí 2 - Kiểm tra thêm bằng chứng (20đ): Đối chiếu hợp đồng, hóa đơn, thanh toán, giao nhận hoặc nguồn độc lập
Tiêu chí 3 - Đánh giá rủi ro (10đ): Xem xét có dấu hiệu sai sót hoặc gian lận hay không.')
on conflict (set_id, position) do nothing;
insert into public.interview_questions (id, set_id, position, round_number, max_score, prompt, guidance, keywords, rubric, grading_rubric, reference_answer)
values ('ac80129f-9de2-57e6-a2e3-c9f67f05b319', (select id from public.interview_sets where slug = 'r2w-logistics-ops-20261019'), 1, 1, 30, 'Giới thiệu bản thân và vì sao bạn chọn theo đuổi vị trí Chuyên viên Vận hành Logistics?', '', '{}'::text[], '[{"id":"criterion_1","label":"Nền tảng liên quan cụ thể","weight":12,"maxScore":12},{"id":"criterion_2","label":"Lý do đúng bản chất nghề","weight":10,"maxScore":10},{"id":"criterion_3","label":"Từ vựng & Sự tự tin","weight":8,"maxScore":8}]'::jsonb, '[{"id":"criterion_1","label":"Nền tảng liên quan cụ thể","description":"- Tiêu chí 1 - Nền tảng liên quan cụ thể (12đ): Nêu cụ thể ngành học/dự án/kinh nghiệm làm việc thực tế liên quan trực tiếp đến giao nhận, điều phối vận tải, quản lý kho bãi hoặc xử lý chứng từ logistics.","keywords":[],"weight":12,"maxScore":12,"skill":"Nền tảng liên quan cụ thể"},{"id":"criterion_2","label":"Lý do đúng bản chất nghề","description":"- Tiêu chí 2 - Lý do đúng bản chất nghề (10đ): Chỉ ra đúng đặc thù công việc Logistics Operations là theo dõi đơn hàng, điều phối hiện trường, xử lý sự cố phát sinh và quản lý luồng hàng; không nhầm với Nhân viên Kinh doanh cước (Sales Logistics) hay Thu mua.","keywords":[],"weight":10,"maxScore":10,"skill":"Lý do đúng bản chất nghề"},{"id":"criterion_3","label":"Từ vựng & Sự tự tin","description":"- Tiêu chí 3 - Từ vựng & Sự tự tin (8đ): Trình bày mạch lạc, dùng đúng thuật ngữ cơ bản: SLA, Lead Time, POD, Inbound/Outbound, Carrier","keywords":[],"weight":8,"maxScore":8,"skill":"Từ vựng & Sự tự tin"}]'::jsonb, '- Tiêu chí 1 - Nền tảng liên quan cụ thể (12đ): Nêu cụ thể ngành học/dự án/kinh nghiệm làm việc thực tế liên quan trực tiếp đến giao nhận, điều phối vận tải, quản lý kho bãi hoặc xử lý chứng từ logistics.
- Tiêu chí 2 - Lý do đúng bản chất nghề (10đ): Chỉ ra đúng đặc thù công việc Logistics Operations là theo dõi đơn hàng, điều phối hiện trường, xử lý sự cố phát sinh và quản lý luồng hàng; không nhầm với Nhân viên Kinh doanh cước (Sales Logistics) hay Thu mua.
- Tiêu chí 3 - Từ vựng & Sự tự tin (8đ): Trình bày mạch lạc, dùng đúng thuật ngữ cơ bản: SLA, Lead Time, POD, Inbound/Outbound, Carrier')
on conflict (set_id, position) do nothing;
insert into public.interview_questions (id, set_id, position, round_number, max_score, prompt, guidance, keywords, rubric, grading_rubric, reference_answer)
values ('1094fe70-efd9-566c-899d-b6713f8c2347', (select id from public.interview_sets where slug = 'r2w-logistics-ops-20261019'), 2, 1, 35, 'Bạn hiểu vai trò của một Chuyên viên Vận hành Logistics trong doanh nghiệp là gì?', '', '{}'::text[], '[{"id":"criterion_1","label":"Xác định đúng vai trò","weight":15,"maxScore":15},{"id":"criterion_2","label":"Liệt kê đủ đầu việc cốt lõi","weight":12,"maxScore":12},{"id":"criterion_3","label":"Từ vựng & Sự tự tin","weight":8,"maxScore":8}]'::jsonb, '[{"id":"criterion_1","label":"Xác định đúng vai trò","description":"- Tiêu chí 1 - Xác định đúng vai trò (15đ): Nêu rõ đây là cầu nối trung tâm giữa Kho - Nhà vận chuyển - Tài xế - Khách hàng để đảm bảo hàng hóa luân chuyển đúng tiến độ, an toàn và đúng quy trình SOP.","keywords":[],"weight":15,"maxScore":15,"skill":"Xác định đúng vai trò"},{"id":"criterion_2","label":"Liệt kê đủ đầu việc cốt lõi","description":"- Tiêu chí 2 - Liệt kê đủ đầu việc cốt lõi (12đ): Nêu tối thiểu 3/5 đầu việc: Theo dõi trạng thái đơn hàng, kiểm tra/lưu trữ chứng từ (Bill/POD), điều phối xe bốc xếp, xử lý ngoại lệ (trễ/hỏng xe), theo dõi chi phí & hiệu suất.","keywords":[],"weight":12,"maxScore":12,"skill":"Liệt kê đủ đầu việc cốt lõi"},{"id":"criterion_3","label":"Từ vựng & Sự tự tin","description":"- Tiêu chí 3 - Từ vựng & Sự tự tin (8đ): Dùng đúng thuật ngữ: SOP, 3PL, Exception Handling, Dispatch, Tracking.","keywords":[],"weight":8,"maxScore":8,"skill":"Từ vựng & Sự tự tin"}]'::jsonb, '- Tiêu chí 1 - Xác định đúng vai trò (15đ): Nêu rõ đây là cầu nối trung tâm giữa Kho - Nhà vận chuyển - Tài xế - Khách hàng để đảm bảo hàng hóa luân chuyển đúng tiến độ, an toàn và đúng quy trình SOP.
- Tiêu chí 2 - Liệt kê đủ đầu việc cốt lõi (12đ): Nêu tối thiểu 3/5 đầu việc: Theo dõi trạng thái đơn hàng, kiểm tra/lưu trữ chứng từ (Bill/POD), điều phối xe bốc xếp, xử lý ngoại lệ (trễ/hỏng xe), theo dõi chi phí & hiệu suất.
- Tiêu chí 3 - Từ vựng & Sự tự tin (8đ): Dùng đúng thuật ngữ: SOP, 3PL, Exception Handling, Dispatch, Tracking.')
on conflict (set_id, position) do nothing;
insert into public.interview_questions (id, set_id, position, round_number, max_score, prompt, guidance, keywords, rubric, grading_rubric, reference_answer)
values ('21a37fbb-a6ab-5a6c-bedb-faead1699654', (select id from public.interview_sets where slug = 'r2w-logistics-ops-20261019'), 3, 1, 35, 'Bạn đã từng tham gia bài tập/dự án hoặc trải nghiệm thực tế nào liên quan đến điều phối và vận hành hàng hóa chưa?', '', '{}'::text[], '[{"id":"criterion_1","label":"Ví dụ dự án cụ thể","weight":15,"maxScore":15},{"id":"criterion_2","label":"Trình bày có ý theo cấu trúc STAR","weight":12,"maxScore":12},{"id":"criterion_3","label":"Rút ra bài học cụ thể","weight":8,"maxScore":8}]'::jsonb, '[{"id":"criterion_1","label":"Ví dụ dự án cụ thể","description":"- Tiêu chí 1 - Ví dụ dự án cụ thể (15đ): Không trả lời \"chưa có kinh nghiệm\" chung chung — nêu tên/bối cảnh bài tập mô phỏng, dự án sinh viên hoặc đợt thực tập cụ thể, vai trò đảm nhận rõ ràng.","keywords":[],"weight":15,"maxScore":15,"skill":"Ví dụ dự án cụ thể"},{"id":"criterion_2","label":"Trình bày có ý theo cấu trúc STAR","description":"- Tiêu chí 2 - Trình bày có ý theo cấu trúc STAR (12đ): Bối cảnh (Situation)  Nhiệm vụ (Task)  Hành động cụ thể (Action)  Kết quả đo lường được (Result).","keywords":[],"weight":12,"maxScore":12,"skill":"Trình bày có ý theo cấu trúc STAR"},{"id":"criterion_3","label":"Rút ra bài học cụ thể","description":"- Tiêu chí 3 - Rút ra bài học cụ thể (8đ): Chỉ ra 1 bài học nghiệp vụ thực tế, ví dụ: \"phải kiểm tra chéo chứng từ trước khi xuất kho và luôn nhận phản hồi xác nhận từ tài xế\".","keywords":[],"weight":8,"maxScore":8,"skill":"Rút ra bài học cụ thể"}]'::jsonb, '- Tiêu chí 1 - Ví dụ dự án cụ thể (15đ): Không trả lời "chưa có kinh nghiệm" chung chung — nêu tên/bối cảnh bài tập mô phỏng, dự án sinh viên hoặc đợt thực tập cụ thể, vai trò đảm nhận rõ ràng.
- Tiêu chí 2 - Trình bày có ý theo cấu trúc STAR (12đ): Bối cảnh (Situation)  Nhiệm vụ (Task)  Hành động cụ thể (Action)  Kết quả đo lường được (Result).
- Tiêu chí 3 - Rút ra bài học cụ thể (8đ): Chỉ ra 1 bài học nghiệp vụ thực tế, ví dụ: "phải kiểm tra chéo chứng từ trước khi xuất kho và luôn nhận phản hồi xác nhận từ tài xế".')
on conflict (set_id, position) do nothing;
insert into public.interview_questions (id, set_id, position, round_number, max_score, prompt, guidance, keywords, rubric, grading_rubric, reference_answer)
values ('2e9e4d71-408d-507e-98d2-92145897d20f', (select id from public.interview_sets where slug = 'r2w-logistics-ops-20261019'), 4, 2, 30, 'Trình bày các bước trong quy trình vận hành đơn hàng (Order Fulfillment Cycle) từ khi nhận yêu cầu đến khi hoàn tất giao hàng?', '', '{}'::text[], '[{"id":"criterion_1","label":"Liệt kê đúng trình tự các bước","weight":12,"maxScore":12},{"id":"criterion_2","label":"Giải thích điểm kiểm soát SOP","weight":12,"maxScore":12},{"id":"criterion_3","label":"Từ vựng & Sự tự tin","weight":6,"maxScore":6}]'::jsonb, '[{"id":"criterion_1","label":"Liệt kê đúng trình tự các bước","description":"- Tiêu chí 1 - Liệt kê đúng trình tự các bước (12đ): Tiếp nhận yêu cầu  Kiểm tra tồn kho & chứng từ  Điều phối kho/xe bốc xếp  Theo dõi hành trình  Xác nhận giao hàng (POD).","keywords":[],"weight":12,"maxScore":12,"skill":"Liệt kê đúng trình tự các bước"},{"id":"criterion_2","label":"Giải thích điểm kiểm soát SOP","description":"- Tiêu chí 2 - Giải thích điểm kiểm soát SOP (12đ): Nêu rõ nguyên tắc không xuất hàng khi lệch chứng từ và chỉ đánh dấu hoàn tất khi nhận được bằng chứng giao hàng (POD).","keywords":[],"weight":12,"maxScore":12,"skill":"Giải thích điểm kiểm soát SOP"},{"id":"criterion_3","label":"Từ vựng & Sự tự tin","description":"- Tiêu chí 3 - Từ vựng & Sự tự tin (6đ): Dùng đúng thuật ngữ: Order Processing, Dispatch, Cross-docking, Proof of Delivery (POD).","keywords":[],"weight":6,"maxScore":6,"skill":"Từ vựng & Sự tự tin"}]'::jsonb, '- Tiêu chí 1 - Liệt kê đúng trình tự các bước (12đ): Tiếp nhận yêu cầu  Kiểm tra tồn kho & chứng từ  Điều phối kho/xe bốc xếp  Theo dõi hành trình  Xác nhận giao hàng (POD).
- Tiêu chí 2 - Giải thích điểm kiểm soát SOP (12đ): Nêu rõ nguyên tắc không xuất hàng khi lệch chứng từ và chỉ đánh dấu hoàn tất khi nhận được bằng chứng giao hàng (POD).
- Tiêu chí 3 - Từ vựng & Sự tự tin (6đ): Dùng đúng thuật ngữ: Order Processing, Dispatch, Cross-docking, Proof of Delivery (POD).')
on conflict (set_id, position) do nothing;
insert into public.interview_questions (id, set_id, position, round_number, max_score, prompt, guidance, keywords, rubric, grading_rubric, reference_answer)
values ('f7daec33-5ae5-5f78-aaff-f6ee85e83106', (select id from public.interview_sets where slug = 'r2w-logistics-ops-20261019'), 5, 2, 35, 'Khi nào nên chọn điều kiện giao hàng Incoterms FOB và CIF trong xuất nhập khẩu hàng hóa?', '', '{}'::text[], '[{"id":"criterion_1","label":"Lựa chọn đúng theo bản chất","weight":18,"maxScore":18},{"id":"criterion_2","label":"Giải thích chuyển giao rủi ro & chi phí","weight":10,"maxScore":10},{"id":"criterion_3","label":"Từ vựng & Sự tự tin","weight":7,"maxScore":7}]'::jsonb, '[{"id":"criterion_1","label":"Lựa chọn đúng theo bản chất","description":"- Tiêu chí 1 - Lựa chọn đúng theo bản chất (18đ): Bán CIF cho hàng xuất nông sản/giá trị thấp để chủ động cước tàu & chuỗi lạnh; Mua FOB cho hàng nhập điện tử/giá trị cao để tự chủ bảo hiểm và chỉ định nhà vận chuyển uy tín tại Việt Nam.","keywords":[],"weight":18,"maxScore":18,"skill":"Lựa chọn đúng theo bản chất"},{"id":"criterion_2","label":"Giải thích chuyển giao rủi ro & chi phí","description":"- Tiêu chí 2 - Giải thích chuyển giao rủi ro & chi phí (10đ): Giải thích đúng điểm chuyển giao rủi ro hàng hóa và nghĩa vụ trả cước tàu/bảo hiểm theo Incoterms 2020.","keywords":[],"weight":10,"maxScore":10,"skill":"Giải thích chuyển giao rủi ro & chi phí"},{"id":"criterion_3","label":"Từ vựng & Sự tự tin","description":"- Tiêu chí 3 - Từ vựng & Sự tự tin (7đ): Dùng đúng thuật ngữ: Freight, Insurance, Port of Loading, Port of Discharge, Risk Transfer.","keywords":[],"weight":7,"maxScore":7,"skill":"Từ vựng & Sự tự tin"}]'::jsonb, '- Tiêu chí 1 - Lựa chọn đúng theo bản chất (18đ): Bán CIF cho hàng xuất nông sản/giá trị thấp để chủ động cước tàu & chuỗi lạnh; Mua FOB cho hàng nhập điện tử/giá trị cao để tự chủ bảo hiểm và chỉ định nhà vận chuyển uy tín tại Việt Nam.
- Tiêu chí 2 - Giải thích chuyển giao rủi ro & chi phí (10đ): Giải thích đúng điểm chuyển giao rủi ro hàng hóa và nghĩa vụ trả cước tàu/bảo hiểm theo Incoterms 2020.
- Tiêu chí 3 - Từ vựng & Sự tự tin (7đ): Dùng đúng thuật ngữ: Freight, Insurance, Port of Loading, Port of Discharge, Risk Transfer.')
on conflict (set_id, position) do nothing;
insert into public.interview_questions (id, set_id, position, round_number, max_score, prompt, guidance, keywords, rubric, grading_rubric, reference_answer)
values ('adb4227d-1e81-50ee-b740-3e96c204d83d', (select id from public.interview_sets where slug = 'r2w-logistics-ops-20261019'), 6, 2, 35, 'Bạn làm thế nào để kiểm soát chi phí vận hành và rủi ro trễ hạn cam kết giao hàng (SLA)?', '', '{}'::text[], '[{"id":"criterion_1","label":"Biện pháp kiểm soát SLA","weight":15,"maxScore":15},{"id":"criterion_2","label":"Tuân thủ thẩm quyền chi phí","weight":12,"maxScore":12},{"id":"criterion_3","label":"Từ vựng & Sự tự tin","weight":8,"maxScore":8}]'::jsonb, '[{"id":"criterion_1","label":"Biện pháp kiểm soát SLA","description":"- Tiêu chí 1 - Biện pháp kiểm soát SLA (15đ): Thiết lập đệm thời gian (Buffer time), theo dõi vị trí xe định kỳ và giám sát mốc thời gian bốc xếp tại kho.","keywords":[],"weight":15,"maxScore":15,"skill":"Biện pháp kiểm soát SLA"},{"id":"criterion_2","label":"Tuân thủ thẩm quyền chi phí","description":"- Tiêu chí 2 - Tuân thủ thẩm quyền chi phí (12đ): Nhấn mạnh nguyên tắc không tự ý xác nhận các khoản phụ phí phát sinh vượt ngưỡng quy định (VD: > 200.000đ) khi chưa được Quản lý phê duyệt.","keywords":[],"weight":12,"maxScore":12,"skill":"Tuân thủ thẩm quyền chi phí"},{"id":"criterion_3","label":"Từ vựng & Sự tự tin","description":"- Tiêu chí 3 - Từ vựng & Sự tự tin (8đ): Dùng đúng thuật ngữ: SLA Margin, Buffer Time, Surcharge, Escalation, Cost Control.","keywords":[],"weight":8,"maxScore":8,"skill":"Từ vựng & Sự tự tin"}]'::jsonb, '- Tiêu chí 1 - Biện pháp kiểm soát SLA (15đ): Thiết lập đệm thời gian (Buffer time), theo dõi vị trí xe định kỳ và giám sát mốc thời gian bốc xếp tại kho.
- Tiêu chí 2 - Tuân thủ thẩm quyền chi phí (12đ): Nhấn mạnh nguyên tắc không tự ý xác nhận các khoản phụ phí phát sinh vượt ngưỡng quy định (VD: > 200.000đ) khi chưa được Quản lý phê duyệt.
- Tiêu chí 3 - Từ vựng & Sự tự tin (8đ): Dùng đúng thuật ngữ: SLA Margin, Buffer Time, Surcharge, Escalation, Cost Control.')
on conflict (set_id, position) do nothing;
insert into public.interview_questions (id, set_id, position, round_number, max_score, prompt, guidance, keywords, rubric, grading_rubric, reference_answer)
values ('2b7bc383-8e5a-5843-bf03-380e377be290', (select id from public.interview_sets where slug = 'r2w-logistics-ops-20261019'), 7, 3, 50, 'Nhân viên kho báo Phiếu giao hàng ghi 30 thùng nhưng Đơn hàng (PO) ghi 32 thùng, xe chở hàng đang chờ rời kho, bạn xử lý thế nào?', '', '{}'::text[], '[{"id":"criterion_1","label":"Xác minh & Tuân thủ SOP","weight":20,"maxScore":20},{"id":"criterion_2","label":"Xử lý chứng từ & Thông báo","weight":20,"maxScore":20},{"id":"criterion_3","label":"Từ vựng & Sự tự tin","weight":10,"maxScore":10}]'::jsonb, '[{"id":"criterion_1","label":"Xác minh & Tuân thủ SOP","description":"- Tiêu chí 1 - Xác minh & Tuân thủ SOP (20đ): Lập tức ra lệnh tạm dừng xuất hàng; không tự ý sửa số liệu; yêu cầu Kho kiểm đếm thực tế và đối chiếu PO/Biên bản.","keywords":[],"weight":20,"maxScore":20,"skill":"Xác minh & Tuân thủ SOP"},{"id":"criterion_2","label":"Xử lý chứng từ & Thông báo","description":"- Tiêu chí 2 - Xử lý chứng từ & Thông báo (20đ): Yêu cầu in lại phiếu giao đúng số lượng thực xuất trước khi cho xe rời kho; cập nhật thông tin minh bạch cho các bên liên quan.","keywords":[],"weight":20,"maxScore":20,"skill":"Xử lý chứng từ & Thông báo"},{"id":"criterion_3","label":"Từ vựng & Sự tự tin","description":"- Tiêu chí 3 - Từ vựng & Sự tự tin (10đ): Dùng đúng thuật ngữ: Document Discrepancy, Hold Shipment, PO Reconciliation, Packing List.","keywords":[],"weight":10,"maxScore":10,"skill":"Từ vựng & Sự tự tin"}]'::jsonb, '- Tiêu chí 1 - Xác minh & Tuân thủ SOP (20đ): Lập tức ra lệnh tạm dừng xuất hàng; không tự ý sửa số liệu; yêu cầu Kho kiểm đếm thực tế và đối chiếu PO/Biên bản.
- Tiêu chí 2 - Xử lý chứng từ & Thông báo (20đ): Yêu cầu in lại phiếu giao đúng số lượng thực xuất trước khi cho xe rời kho; cập nhật thông tin minh bạch cho các bên liên quan.
- Tiêu chí 3 - Từ vựng & Sự tự tin (10đ): Dùng đúng thuật ngữ: Document Discrepancy, Hold Shipment, PO Reconciliation, Packing List.')
on conflict (set_id, position) do nothing;
insert into public.interview_questions (id, set_id, position, round_number, max_score, prompt, guidance, keywords, rubric, grading_rubric, reference_answer)
values ('4c8faa86-042d-58ae-8c02-bb7a8d0eb443', (select id from public.interview_sets where slug = 'r2w-logistics-ops-20261019'), 8, 3, 50, 'Xe chở hàng gặp sự cố hỏng trên đường có nguy cơ trễ SLA 1 tiếng. Xe thay thế ngoài có thể giao đúng hạn nhưng phát sinh phụ phí 350.000đ (vượt hạn mức tự duyệt 200.000đ), bạn làm gì?', '', '{}'::text[], '[{"id":"criterion_1","label":"Tuân thủ thẩm quyền & Khẩn cấp","weight":20,"maxScore":20},{"id":"criterion_2","label":"Phương án dự phòng","weight":20,"maxScore":20},{"id":"criterion_3","label":"Từ vựng & Sự tự tin","weight":10,"maxScore":10}]'::jsonb, '[{"id":"criterion_1","label":"Tuân thủ thẩm quyền & Khẩn cấp","description":"- Tiêu chí 1 - Tuân thủ thẩm quyền & Khẩn cấp (20đ): Liên hệ Quản lý ngay lập tức để trình duyệt khoản phụ phí 350.000đ trước hạn báo giá của nhà xe (VD: trước 09:35) để đảm bảo SLA.","keywords":[],"weight":20,"maxScore":20,"skill":"Tuân thủ thẩm quyền & Khẩn cấp"},{"id":"criterion_2","label":"Phương án dự phòng","description":"- Tiêu chí 2 - Phương án dự phòng (20đ): Nếu Quản lý không duyệt chi phí, chủ động liên hệ ngay với Khách hàng để thông báo rủi ro trễ tiến độ và xin gia hạn thời gian giao.","keywords":[],"weight":20,"maxScore":20,"skill":"Phương án dự phòng"},{"id":"criterion_3","label":"Từ vựng & Sự tự tin","description":"- Tiêu chí 3 - Từ vựng & Sự tự tin (10đ): Dùng đúng thuật ngữ: Escalation, Emergency Transport, SLA Violation, Contingency Plan.","keywords":[],"weight":10,"maxScore":10,"skill":"Từ vựng & Sự tự tin"}]'::jsonb, '- Tiêu chí 1 - Tuân thủ thẩm quyền & Khẩn cấp (20đ): Liên hệ Quản lý ngay lập tức để trình duyệt khoản phụ phí 350.000đ trước hạn báo giá của nhà xe (VD: trước 09:35) để đảm bảo SLA.
- Tiêu chí 2 - Phương án dự phòng (20đ): Nếu Quản lý không duyệt chi phí, chủ động liên hệ ngay với Khách hàng để thông báo rủi ro trễ tiến độ và xin gia hạn thời gian giao.
- Tiêu chí 3 - Từ vựng & Sự tự tin (10đ): Dùng đúng thuật ngữ: Escalation, Emergency Transport, SLA Violation, Contingency Plan.')
on conflict (set_id, position) do nothing;
insert into public.interview_questions (id, set_id, position, round_number, max_score, prompt, guidance, keywords, rubric, grading_rubric, reference_answer)
values ('5d1f91fc-9039-59ab-810c-05213bede3de', (select id from public.interview_sets where slug = 'r2w-purchasing-20261019'), 1, 1, 30, 'Giới thiệu bản thân và vì sao bạn chọn theo đuổi nghề Thu mua (Purchasing/Procurement)?', '', '{}'::text[], '[{"id":"criterion_1","label":"Nền tảng liên quan cụ thể","weight":12,"maxScore":12},{"id":"criterion_2","label":"Lý do đúng bản chất nghề","weight":10,"maxScore":10},{"id":"criterion_3","label":"Từ vựng & Sự tự tin","weight":8,"maxScore":8}]'::jsonb, '[{"id":"criterion_1","label":"Nền tảng liên quan cụ thể","description":"- Tiêu chí 1 - Nền tảng liên quan cụ thể (12đ): Nêu ngành học/dự án/kinh nghiệm thực tế liên quan đến thương mại, đàm phán báo giá, đánh giá nhà cung cấp hoặc quản lý hợp đồng.","keywords":[],"weight":12,"maxScore":12,"skill":"Nền tảng liên quan cụ thể"},{"id":"criterion_2","label":"Lý do đúng bản chất nghề","description":"- Tiêu chí 2 - Lý do đúng bản chất nghề (10đ): Chỉ ra đúng đặc thù nghề Thu mua là tối ưu tổng chi phí (Landed Cost), quản lý rủi ro nhà cung cấp và đảm bảo nguồn cung đúng SLA; không nhầm với Sales hay Kế toán.","keywords":[],"weight":10,"maxScore":10,"skill":"Lý do đúng bản chất nghề"},{"id":"criterion_3","label":"Từ vựng & Sự tự tin","description":"- Tiêu chí 3 - Từ vựng & Sự tự tin (8đ): Trình bày mạch lạc, dùng đúng thuật ngữ: Procurement, Landed Cost, Vendor Management, PO, PR.","keywords":[],"weight":8,"maxScore":8,"skill":"Từ vựng & Sự tự tin"}]'::jsonb, '- Tiêu chí 1 - Nền tảng liên quan cụ thể (12đ): Nêu ngành học/dự án/kinh nghiệm thực tế liên quan đến thương mại, đàm phán báo giá, đánh giá nhà cung cấp hoặc quản lý hợp đồng.
- Tiêu chí 2 - Lý do đúng bản chất nghề (10đ): Chỉ ra đúng đặc thù nghề Thu mua là tối ưu tổng chi phí (Landed Cost), quản lý rủi ro nhà cung cấp và đảm bảo nguồn cung đúng SLA; không nhầm với Sales hay Kế toán.
- Tiêu chí 3 - Từ vựng & Sự tự tin (8đ): Trình bày mạch lạc, dùng đúng thuật ngữ: Procurement, Landed Cost, Vendor Management, PO, PR.')
on conflict (set_id, position) do nothing;
insert into public.interview_questions (id, set_id, position, round_number, max_score, prompt, guidance, keywords, rubric, grading_rubric, reference_answer)
values ('f3975118-7bf7-531d-8f1b-837c91f98d5e', (select id from public.interview_sets where slug = 'r2w-purchasing-20261019'), 2, 1, 35, 'Bạn hiểu vai trò của Chuyên viên Thu mua trong doanh nghiệp là gì và làm sao để đảm bảo tính minh bạch, chống rủi ro "bắt tay ngầm" (Kickback)?', '', '{}'::text[], '[{"id":"criterion_1","label":"Xác định đúng vai trò","weight":15,"maxScore":15},{"id":"criterion_2","label":"Biện pháp chống rủi ro minh bạch","weight":12,"maxScore":12},{"id":"criterion_3","label":"Từ vựng & Sự tự tin","weight":8,"maxScore":8}]'::jsonb, '[{"id":"criterion_1","label":"Xác định đúng vai trò","description":"- Tiêu chí 1 - Xác định đúng vai trò (15đ): Đầu mối tìm kiếm, đàm phán điều khoản thương mại và quản lý luồng PR-PO đảm bảo mua đúng chất lượng, đúng giá và đúng thời điểm.","keywords":[],"weight":15,"maxScore":15,"skill":"Xác định đúng vai trò"},{"id":"criterion_2","label":"Biện pháp chống rủi ro minh bạch","description":"- Tiêu chí 2 - Biện pháp chống rủi ro minh bạch (12đ): Tuân thủ quy trình 3-Quote (tối thiểu 3 báo giá độc lập); phân tách vai trò (Thu mua tìm giá, QA/QC test hàng mẫu); dùng bảng Vendor Scorecard trình Sếp duyệt.","keywords":[],"weight":12,"maxScore":12,"skill":"Biện pháp chống rủi ro minh bạch"},{"id":"criterion_3","label":"Từ vựng & Sự tự tin","description":"- Tiêu chí 3 - Từ vựng & Sự tự tin (8đ): Dùng đúng thuật ngữ: 3-Quote, RFQ, Vendor Scorecard, Anti-Kickback, Transparency.","keywords":[],"weight":8,"maxScore":8,"skill":"Từ vựng & Sự tự tin"}]'::jsonb, '- Tiêu chí 1 - Xác định đúng vai trò (15đ): Đầu mối tìm kiếm, đàm phán điều khoản thương mại và quản lý luồng PR-PO đảm bảo mua đúng chất lượng, đúng giá và đúng thời điểm.
- Tiêu chí 2 - Biện pháp chống rủi ro minh bạch (12đ): Tuân thủ quy trình 3-Quote (tối thiểu 3 báo giá độc lập); phân tách vai trò (Thu mua tìm giá, QA/QC test hàng mẫu); dùng bảng Vendor Scorecard trình Sếp duyệt.
- Tiêu chí 3 - Từ vựng & Sự tự tin (8đ): Dùng đúng thuật ngữ: 3-Quote, RFQ, Vendor Scorecard, Anti-Kickback, Transparency.')
on conflict (set_id, position) do nothing;
insert into public.interview_questions (id, set_id, position, round_number, max_score, prompt, guidance, keywords, rubric, grading_rubric, reference_answer)
values ('46629b73-bcd8-5188-bffa-10fa16ba0f2a', (select id from public.interview_sets where slug = 'r2w-purchasing-20261019'), 3, 1, 35, 'Bạn đã từng tham gia bài tập/dự án nào liên quan đến tìm kiếm hoặc đàm phán với nhà cung cấp chưa?', '', '{}'::text[], '[{"id":"criterion_1","label":"Ví dụ dự án cụ thể","weight":15,"maxScore":15},{"id":"criterion_2","label":"Trình bày theo cấu trúc STAR","weight":12,"maxScore":12},{"id":"criterion_3","label":"Rút ra bài học cụ thể","weight":8,"maxScore":8}]'::jsonb, '[{"id":"criterion_1","label":"Ví dụ dự án cụ thể","description":"- Tiêu chí 1 - Ví dụ dự án cụ thể (15đ): Nêu tên dự án/bài tập cụ thể (Sourcing bao bì, đàm phán báo giá vật tư, thay thế NCC kém chất lượng...), mô tả vai trò rõ ràng.","keywords":[],"weight":15,"maxScore":15,"skill":"Ví dụ dự án cụ thể"},{"id":"criterion_2","label":"Trình bày theo cấu trúc STAR","description":"- Tiêu chí 2 - Trình bày theo cấu trúc STAR (12đ): Bối cảnh (Situation)  Nhiệm vụ (Task)  Hành động đàm phán/sourcing (Action)  Kết quả tiết kiệm chi phí/đảm bảo tiến độ (Result).","keywords":[],"weight":12,"maxScore":12,"skill":"Trình bày theo cấu trúc STAR"},{"id":"criterion_3","label":"Rút ra bài học cụ thể","description":"- Tiêu chí 3 - Rút ra bài học cụ thể (8đ): Chỉ ra 1 bài học thực tế, ví dụ: \"phải so sánh Tổng chi phí thực tế (Landed Cost) chứ không chỉ nhìn vào đơn giá rẻ nhất\".","keywords":[],"weight":8,"maxScore":8,"skill":"Rút ra bài học cụ thể"}]'::jsonb, '- Tiêu chí 1 - Ví dụ dự án cụ thể (15đ): Nêu tên dự án/bài tập cụ thể (Sourcing bao bì, đàm phán báo giá vật tư, thay thế NCC kém chất lượng...), mô tả vai trò rõ ràng.
- Tiêu chí 2 - Trình bày theo cấu trúc STAR (12đ): Bối cảnh (Situation)  Nhiệm vụ (Task)  Hành động đàm phán/sourcing (Action)  Kết quả tiết kiệm chi phí/đảm bảo tiến độ (Result).
- Tiêu chí 3 - Rút ra bài học cụ thể (8đ): Chỉ ra 1 bài học thực tế, ví dụ: "phải so sánh Tổng chi phí thực tế (Landed Cost) chứ không chỉ nhìn vào đơn giá rẻ nhất".')
on conflict (set_id, position) do nothing;
insert into public.interview_questions (id, set_id, position, round_number, max_score, prompt, guidance, keywords, rubric, grading_rubric, reference_answer)
values ('c2007b36-c069-517d-806e-f6265bc4bd26', (select id from public.interview_sets where slug = 'r2w-purchasing-20261019'), 4, 2, 30, 'Trình bày quy trình Sourcing nhà cung cấp mới từ khi nhận Yêu cầu mua hàng (PR) đến khi hoàn tất ký hợp đồng/PO?', '', '{}'::text[], '[{"id":"criterion_1","label":"Liệt kê đủ các bước chuẩn","weight":12,"maxScore":12},{"id":"criterion_2","label":"Nắm vững quy định SOP","weight":12,"maxScore":12},{"id":"criterion_3","label":"Từ vựng & Sự tự tin","weight":6,"maxScore":6}]'::jsonb, '[{"id":"criterion_1","label":"Liệt kê đủ các bước chuẩn","description":"- Tiêu chí 1 - Liệt kê đủ các bước chuẩn (12đ): Tiếp nhận PR  Tìm nguồn cung  Gửi RFQ cho  bên  Bảng so sánh giá (Cost Matrix)  Test mẫu (Sample Audit)  Đàm phán  Trình duyệt & Ký PO/Hợp đồng.","keywords":[],"weight":12,"maxScore":12,"skill":"Liệt kê đủ các bước chuẩn"},{"id":"criterion_2","label":"Nắm vững quy định SOP","description":"- Tiêu chí 2 - Nắm vững quy định SOP (12đ): Nhấn mạnh mọi đơn hàng trên hạn mức (VD: > 100 triệu) bắt buộc phải lập Tờ trình xin ý kiến Trưởng phòng phê duyệt trước khi phát hành PO.","keywords":[],"weight":12,"maxScore":12,"skill":"Nắm vững quy định SOP"},{"id":"criterion_3","label":"Từ vựng & Sự tự tin","description":"- Tiêu chí 3 - Từ vựng & Sự tự tin (6đ): Dùng đúng thuật ngữ: PR, PO, RFQ, Cost Comparison Matrix, Sample Audit, Contract.","keywords":[],"weight":6,"maxScore":6,"skill":"Từ vựng & Sự tự tin"}]'::jsonb, '- Tiêu chí 1 - Liệt kê đủ các bước chuẩn (12đ): Tiếp nhận PR  Tìm nguồn cung  Gửi RFQ cho  bên  Bảng so sánh giá (Cost Matrix)  Test mẫu (Sample Audit)  Đàm phán  Trình duyệt & Ký PO/Hợp đồng.
- Tiêu chí 2 - Nắm vững quy định SOP (12đ): Nhấn mạnh mọi đơn hàng trên hạn mức (VD: > 100 triệu) bắt buộc phải lập Tờ trình xin ý kiến Trưởng phòng phê duyệt trước khi phát hành PO.
- Tiêu chí 3 - Từ vựng & Sự tự tin (6đ): Dùng đúng thuật ngữ: PR, PO, RFQ, Cost Comparison Matrix, Sample Audit, Contract.')
on conflict (set_id, position) do nothing;
insert into public.interview_questions (id, set_id, position, round_number, max_score, prompt, guidance, keywords, rubric, grading_rubric, reference_answer)
values ('0e2df989-99b3-5bba-91ad-c4d78cd78e08', (select id from public.interview_sets where slug = 'r2w-purchasing-20261019'), 5, 2, 35, 'Khái niệm Tổng chi phí thực tế (Landed Cost) là gì và làm thế nào để lựa chọn giữa các báo giá có điều kiện khác nhau?', '', '{}'::text[], '[{"id":"criterion_1","label":"Nêu đúng công thức Landed Cost","weight":18,"maxScore":18},{"id":"criterion_2","label":"Phân tích Đánh đổi Thương mại","weight":10,"maxScore":10},{"id":"criterion_3","label":"Từ vựng & Sự tự tin","weight":7,"maxScore":7}]'::jsonb, '[{"id":"criterion_1","label":"Nêu đúng công thức Landed Cost","description":"- Tiêu chí 1 - Nêu đúng công thức Landed Cost (18đ): Landed Cost = Đơn giá có VAT + Vận chuyển/Bảo hiểm + Lưu kho/Thủ tục phát sinh","keywords":[],"weight":18,"maxScore":18,"skill":"Nêu đúng công thức Landed Cost"},{"id":"criterion_2","label":"Phân tích Đánh đổi Thương mại","description":"- Tiêu chí 2 - Phân tích Đánh đổi Thương mại (10đ): Lựa chọn NCC có Landed Cost hợp lý, đáp ứng SLA và cho trả chậm 30 ngày (tối ưu dòng tiền) hơn là chọn NCC giá rẻ nhưng bắt trả trước 100% hoặc trễ SLA.","keywords":[],"weight":10,"maxScore":10,"skill":"Phân tích Đánh đổi Thương mại"},{"id":"criterion_3","label":"Từ vựng & Sự tự tin","description":"- Tiêu chí 3 - Từ vựng & Sự tự tin (7đ): Dùng đúng thuật ngữ: Landed Cost, VAT, Working Capital, Trade-off, Payment Terms.","keywords":[],"weight":7,"maxScore":7,"skill":"Từ vựng & Sự tự tin"}]'::jsonb, '- Tiêu chí 1 - Nêu đúng công thức Landed Cost (18đ): Landed Cost = Đơn giá có VAT + Vận chuyển/Bảo hiểm + Lưu kho/Thủ tục phát sinh
- Tiêu chí 2 - Phân tích Đánh đổi Thương mại (10đ): Lựa chọn NCC có Landed Cost hợp lý, đáp ứng SLA và cho trả chậm 30 ngày (tối ưu dòng tiền) hơn là chọn NCC giá rẻ nhưng bắt trả trước 100% hoặc trễ SLA.
- Tiêu chí 3 - Từ vựng & Sự tự tin (7đ): Dùng đúng thuật ngữ: Landed Cost, VAT, Working Capital, Trade-off, Payment Terms.')
on conflict (set_id, position) do nothing;
insert into public.interview_questions (id, set_id, position, round_number, max_score, prompt, guidance, keywords, rubric, grading_rubric, reference_answer)
values ('da578d8c-af4d-5a86-99a8-857aa3048263', (select id from public.interview_sets where slug = 'r2w-purchasing-20261019'), 6, 2, 35, 'Khi nhà cung cấp giao lô hàng bị lỗi kỹ thuật 20%, bạn phối hợp xử lý như thế nào để đảm bảo không gián đoạn sản xuất?', '', '{}'::text[], '[{"id":"criterion_1","label":"Lập biên bản & Căn cứ","weight":15,"maxScore":15},{"id":"criterion_2","label":"Đề xuất phương án kiên quyết","weight":12,"maxScore":12},{"id":"criterion_3","label":"Từ vựng & Sự tự tin","weight":8,"maxScore":8}]'::jsonb, '[{"id":"criterion_1","label":"Lập biên bản & Căn cứ","description":"- Tiêu chí 1 - Lập biên bản & Căn cứ (15đ): Yêu cầu biên bản kiểm hàng từ Kho/QA-QC; gửi thư khiếu nại chính thức cho NCC kèm số liệu sản phẩm lỗi cụ thể.","keywords":[],"weight":15,"maxScore":15,"skill":"Lập biên bản & Căn cứ"},{"id":"criterion_2","label":"Đề xuất phương án kiên quyết","description":"- Tiêu chí 2 - Đề xuất phương án kiên quyết (12đ): Yêu cầu NCC đổi bù đủ hàng đạt chuẩn trong 48h HOẶC cấn trừ giá trị hàng lỗi trực tiếp vào công nợ đơn sau.","keywords":[],"weight":12,"maxScore":12,"skill":"Đề xuất phương án kiên quyết"},{"id":"criterion_3","label":"Từ vựng & Sự tự tin","description":"- Tiêu chí 3 - Từ vựng & Sự tự tin (8đ): Dùng đúng thuật ngữ: Defect Rate, Quality Claim, Debit Note, Replacement, SOP.","keywords":[],"weight":8,"maxScore":8,"skill":"Từ vựng & Sự tự tin"}]'::jsonb, '- Tiêu chí 1 - Lập biên bản & Căn cứ (15đ): Yêu cầu biên bản kiểm hàng từ Kho/QA-QC; gửi thư khiếu nại chính thức cho NCC kèm số liệu sản phẩm lỗi cụ thể.
- Tiêu chí 2 - Đề xuất phương án kiên quyết (12đ): Yêu cầu NCC đổi bù đủ hàng đạt chuẩn trong 48h HOẶC cấn trừ giá trị hàng lỗi trực tiếp vào công nợ đơn sau.
- Tiêu chí 3 - Từ vựng & Sự tự tin (8đ): Dùng đúng thuật ngữ: Defect Rate, Quality Claim, Debit Note, Replacement, SOP.')
on conflict (set_id, position) do nothing;
insert into public.interview_questions (id, set_id, position, round_number, max_score, prompt, guidance, keywords, rubric, grading_rubric, reference_answer)
values ('60b7b37b-319d-5237-a069-4baf9c4eccab', (select id from public.interview_sets where slug = 'r2w-purchasing-20261019'), 7, 3, 50, 'Nhà cung cấp lâu năm bất ngờ thông báo tăng giá 15% bắt đầu từ đơn hàng sáng mai do giá bột giấy tăng, nếu không đồng ý họ sẽ ngưng cấp hàng, bạn xử lý thế nào?', '', '{}'::text[], '[{"id":"criterion_1","label":"Giữ bình tĩnh & Dùng hợp đồng","weight":20,"maxScore":20},{"id":"criterion_2","label":"Đàm phán Đổi giá trị / Trade-off","weight":20,"maxScore":20},{"id":"criterion_3","label":"Từ vựng & Sự tự tin","weight":10,"maxScore":10}]'::jsonb, '[{"id":"criterion_1","label":"Giữ bình tĩnh & Dùng hợp đồng","description":"- Tiêu chí 1 - Giữ bình tĩnh & Dùng hợp đồng (20đ): Không nổi cáu hay bỏ cuộc ngay; yêu cầu văn bản thông báo chính thức kèm chứng từ chứng minh; dùng điều khoản Hợp đồng (báo trước 15-30 ngày) để bắt buộc giữ giá cũ cho đơn sáng mai.","keywords":[],"weight":20,"maxScore":20,"skill":"Giữ bình tĩnh & Dùng hợp đồng"},{"id":"criterion_2","label":"Đàm phán Đổi giá trị / Trade-off","description":"- Tiêu chí 2 - Đàm phán Đổi giá trị / Trade-off (20đ): Nếu bắt buộc tăng giá đợt sau, thương lượng tăng thời hạn công nợ (30  60 ngày) hoặc cam kết sản lượng (Volume) lớn hơn để khống chế mức tăng giá ở 5% thay vì 15%.","keywords":[],"weight":20,"maxScore":20,"skill":"Đàm phán Đổi giá trị / Trade-off"},{"id":"criterion_3","label":"Từ vựng & Sự tự tin","description":"- Tiêu chí 3 - Từ vựng & Sự tự tin (10đ): Dùng đúng thuật ngữ: Price Increase Notice, Contract Clause, Trade-off, BATNA, Payment Terms.","keywords":[],"weight":10,"maxScore":10,"skill":"Từ vựng & Sự tự tin"}]'::jsonb, '- Tiêu chí 1 - Giữ bình tĩnh & Dùng hợp đồng (20đ): Không nổi cáu hay bỏ cuộc ngay; yêu cầu văn bản thông báo chính thức kèm chứng từ chứng minh; dùng điều khoản Hợp đồng (báo trước 15-30 ngày) để bắt buộc giữ giá cũ cho đơn sáng mai.
- Tiêu chí 2 - Đàm phán Đổi giá trị / Trade-off (20đ): Nếu bắt buộc tăng giá đợt sau, thương lượng tăng thời hạn công nợ (30  60 ngày) hoặc cam kết sản lượng (Volume) lớn hơn để khống chế mức tăng giá ở 5% thay vì 15%.
- Tiêu chí 3 - Từ vựng & Sự tự tin (10đ): Dùng đúng thuật ngữ: Price Increase Notice, Contract Clause, Trade-off, BATNA, Payment Terms.')
on conflict (set_id, position) do nothing;
insert into public.interview_questions (id, set_id, position, round_number, max_score, prompt, guidance, keywords, rubric, grading_rubric, reference_answer)
values ('7b142b9a-33bc-530c-90ce-0f5282f6b50c', (select id from public.interview_sets where slug = 'r2w-purchasing-20261019'), 8, 3, 50, 'Giữa NCC A (Giá rẻ hơn 5%, trả trước 100%) và NCC B (Giá nhỉnh hơn 5%, trả chậm 30 ngày, giao sớm 2 ngày), bạn chọn bên nào và lập luận trình Sếp ra sao?', '', '{}'::text[], '[{"id":"criterion_1","label":"Lựa chọn & Lập luận tối ưu","weight":20,"maxScore":20},{"id":"criterion_2","label":"Chỉ ra rủi ro của NCC A","weight":20,"maxScore":20},{"id":"criterion_3","label":"Từ vựng & Sự tự tin","weight":10,"maxScore":10}]'::jsonb, '[{"id":"criterion_1","label":"Lựa chọn & Lập luận tối ưu","description":"- Tiêu chí 1 - Lựa chọn & Lập luận tối ưu (20đ): Đề xuất chọn NCC B; chứng minh chênh lệch 5% giá được bù đắp hoàn toàn bởi việc giao hàng sớm 2 ngày (đảm bảo an toàn SLA sản xuất) và trả chậm 30 ngày (tối ưu dòng tiền).","keywords":[],"weight":20,"maxScore":20,"skill":"Lựa chọn & Lập luận tối ưu"},{"id":"criterion_2","label":"Chỉ ra rủi ro của NCC A","description":"- Tiêu chí 2 - Chỉ ra rủi ro của NCC A (20đ): Phân tích rủi ro giam vốn khi trả trước 100% và rủi ro chậm tiến độ giao hàng của NCC A.","keywords":[],"weight":20,"maxScore":20,"skill":"Chỉ ra rủi ro của NCC A"},{"id":"criterion_3","label":"Từ vựng & Sự tự tin","description":"- Tiêu chí 3 - Từ vựng & Sự tự tin (10đ): Dùng đúng thuật ngữ: Working Capital, Cash Flow Risk, SLA Margin, Executive Proposal.","keywords":[],"weight":10,"maxScore":10,"skill":"Từ vựng & Sự tự tin"}]'::jsonb, '- Tiêu chí 1 - Lựa chọn & Lập luận tối ưu (20đ): Đề xuất chọn NCC B; chứng minh chênh lệch 5% giá được bù đắp hoàn toàn bởi việc giao hàng sớm 2 ngày (đảm bảo an toàn SLA sản xuất) và trả chậm 30 ngày (tối ưu dòng tiền).
- Tiêu chí 2 - Chỉ ra rủi ro của NCC A (20đ): Phân tích rủi ro giam vốn khi trả trước 100% và rủi ro chậm tiến độ giao hàng của NCC A.
- Tiêu chí 3 - Từ vựng & Sự tự tin (10đ): Dùng đúng thuật ngữ: Working Capital, Cash Flow Risk, SLA Margin, Executive Proposal.')
on conflict (set_id, position) do nothing;
insert into public.interview_questions (id, set_id, position, round_number, max_score, prompt, guidance, keywords, rubric, grading_rubric, reference_answer)
values ('e7af035f-2d9c-5b16-ab33-58535d8ba6cd', (select id from public.interview_sets where slug = 'r2w-supply-chain-20261019'), 1, 1, 30, 'Giới thiệu bản thân và vì sao bạn chọn định hướng trở thành Supply Chain Analyst?', '', '{}'::text[], '[{"id":"criterion_1","label":"Nền tảng liên quan cụ thể","weight":12,"maxScore":12},{"id":"criterion_2","label":"Lý do đúng bản chất nghề","weight":10,"maxScore":10},{"id":"criterion_3","label":"Từ vựng & Sự tự tin","weight":8,"maxScore":8}]'::jsonb, '[{"id":"criterion_1","label":"Nền tảng liên quan cụ thể","description":"- Tiêu chí 1 - Nền tảng liên quan cụ thể (12đ): Nêu ngành học/dự án phân tích dữ liệu, hệ thống thông tin, mô hình hóa dữ liệu bằng Excel, SQL, Power BI hoặc Python liên quan đến chuỗi cung ứng.","keywords":[],"weight":12,"maxScore":12,"skill":"Nền tảng liên quan cụ thể"},{"id":"criterion_2","label":"Lý do đúng bản chất nghề","description":"- Tiêu chí 2 - Lý do đúng bản chất nghề (10đ): Hiểu rõ vai trò Analyst là khai thác dữ liệu, phát hiện bất thường, tìm nguyên nhân gốc rễ và đề xuất giải pháp tối ưu; phân biệt với nhân sự vận hành thuần túy.","keywords":[],"weight":10,"maxScore":10,"skill":"Lý do đúng bản chất nghề"},{"id":"criterion_3","label":"Từ vựng & Sự tự tin","description":"- Tiêu chí 3 - Từ vựng & Sự tự tin (8đ): Trình bày mạch lạc, dùng đúng thuật ngữ: Data Analytics, Inventory Optimization, Supply-Demand, Forecasting.","keywords":[],"weight":8,"maxScore":8,"skill":"Từ vựng & Sự tự tin"}]'::jsonb, '- Tiêu chí 1 - Nền tảng liên quan cụ thể (12đ): Nêu ngành học/dự án phân tích dữ liệu, hệ thống thông tin, mô hình hóa dữ liệu bằng Excel, SQL, Power BI hoặc Python liên quan đến chuỗi cung ứng.
- Tiêu chí 2 - Lý do đúng bản chất nghề (10đ): Hiểu rõ vai trò Analyst là khai thác dữ liệu, phát hiện bất thường, tìm nguyên nhân gốc rễ và đề xuất giải pháp tối ưu; phân biệt với nhân sự vận hành thuần túy.
- Tiêu chí 3 - Từ vựng & Sự tự tin (8đ): Trình bày mạch lạc, dùng đúng thuật ngữ: Data Analytics, Inventory Optimization, Supply-Demand, Forecasting.')
on conflict (set_id, position) do nothing;
insert into public.interview_questions (id, set_id, position, round_number, max_score, prompt, guidance, keywords, rubric, grading_rubric, reference_answer)
values ('3e83772d-efe4-54b6-adaf-d426767806dd', (select id from public.interview_sets where slug = 'r2w-supply-chain-20261019'), 2, 1, 35, 'Bạn hiểu vai trò của một Supply Chain Analyst trong doanh nghiệp là gì?', '', '{}'::text[], '[{"id":"criterion_1","label":"Xác định đúng vai trò","weight":15,"maxScore":15},{"id":"criterion_2","label":"Liệt kê đủ đầu việc cốt lõi","weight":12,"maxScore":12},{"id":"criterion_3","label":"Từ vựng & Sự tự tin","weight":8,"maxScore":8}]'::jsonb, '[{"id":"criterion_1","label":"Xác định đúng vai trò","description":"- Tiêu chí 1 - Xác định đúng vai trò (15đ): Nêu rõ đây là người biến dữ liệu thô trong chuỗi cung ứng thành thông tin quản trị (Actionable Insights) giúp cải thiện hiệu suất và giảm chi phí.","keywords":[],"weight":15,"maxScore":15,"skill":"Xác định đúng vai trò"},{"id":"criterion_2","label":"Liệt kê đủ đầu việc cốt lõi","description":"- Tiêu chí 2 - Liệt kê đủ đầu việc cốt lõi (12đ): Nêu tối thiểu 3/5 công việc: Phân tích tồn kho (DOI/Safety Stock), dự báo nhu cầu (Demand Forecasting), đánh giá KPI nhà cung cấp (OTIF), phân tích chi phí vận chuyển/lưu kho, tìm nguyên nhân gốc rễ đứt gãy.","keywords":[],"weight":12,"maxScore":12,"skill":"Liệt kê đủ đầu việc cốt lõi"},{"id":"criterion_3","label":"Từ vựng & Sự tự tin","description":"- Tiêu chí 3 - Từ vựng & Sự tự tin (8đ): Dùng đúng thuật ngữ: DOI, Safety Stock, OTIF, Lead Time, Actionable Insights.","keywords":[],"weight":8,"maxScore":8,"skill":"Từ vựng & Sự tự tin"}]'::jsonb, '- Tiêu chí 1 - Xác định đúng vai trò (15đ): Nêu rõ đây là người biến dữ liệu thô trong chuỗi cung ứng thành thông tin quản trị (Actionable Insights) giúp cải thiện hiệu suất và giảm chi phí.
- Tiêu chí 2 - Liệt kê đủ đầu việc cốt lõi (12đ): Nêu tối thiểu 3/5 công việc: Phân tích tồn kho (DOI/Safety Stock), dự báo nhu cầu (Demand Forecasting), đánh giá KPI nhà cung cấp (OTIF), phân tích chi phí vận chuyển/lưu kho, tìm nguyên nhân gốc rễ đứt gãy.
- Tiêu chí 3 - Từ vựng & Sự tự tin (8đ): Dùng đúng thuật ngữ: DOI, Safety Stock, OTIF, Lead Time, Actionable Insights.')
on conflict (set_id, position) do nothing;
insert into public.interview_questions (id, set_id, position, round_number, max_score, prompt, guidance, keywords, rubric, grading_rubric, reference_answer)
values ('ebbf6165-ebfc-54e7-9e58-4624f4b0ade3', (select id from public.interview_sets where slug = 'r2w-supply-chain-20261019'), 3, 1, 35, 'Bạn đã từng thực hiện dự án hoặc bài tập phân tích dữ liệu chuỗi cung ứng nào chưa?', '', '{}'::text[], '[{"id":"criterion_1","label":"Ví dụ dự án cụ thể","weight":15,"maxScore":15},{"id":"criterion_2","label":"Trình bày theo cấu trúc STAR","weight":12,"maxScore":12},{"id":"criterion_3","label":"Bài học kinh nghiệm","weight":8,"maxScore":8}]'::jsonb, '[{"id":"criterion_1","label":"Ví dụ dự án cụ thể","description":"- Tiêu chí 1 - Ví dụ dự án cụ thể (15đ): Nêu tên bài tập/dự án cụ thể (phân tích tồn kho, dự báo bán hàng, đánh giá nhà cung cấp...), mô tả nguồn dữ liệu và vai trò đảm nhận.","keywords":[],"weight":15,"maxScore":15,"skill":"Ví dụ dự án cụ thể"},{"id":"criterion_2","label":"Trình bày theo cấu trúc STAR","description":"- Tiêu chí 2 - Trình bày theo cấu trúc STAR (12đ): Bối cảnh (Situation)  Nhiệm vụ (Task)  Hành động phân tích dữ liệu (Action)  Kết quả đo lường được (Result).","keywords":[],"weight":12,"maxScore":12,"skill":"Trình bày theo cấu trúc STAR"},{"id":"criterion_3","label":"Bài học kinh nghiệm","description":"- Tiêu chí 3 - Bài học kinh nghiệm (8đ): Chỉ ra 1 bài học nghiệp vụ, ví dụ: \"phải làm sạch dữ liệu và kiểm tra tính toàn vẹn trước khi đưa ra nhận định\".","keywords":[],"weight":8,"maxScore":8,"skill":"Bài học kinh nghiệm"}]'::jsonb, '- Tiêu chí 1 - Ví dụ dự án cụ thể (15đ): Nêu tên bài tập/dự án cụ thể (phân tích tồn kho, dự báo bán hàng, đánh giá nhà cung cấp...), mô tả nguồn dữ liệu và vai trò đảm nhận.
- Tiêu chí 2 - Trình bày theo cấu trúc STAR (12đ): Bối cảnh (Situation)  Nhiệm vụ (Task)  Hành động phân tích dữ liệu (Action)  Kết quả đo lường được (Result).
- Tiêu chí 3 - Bài học kinh nghiệm (8đ): Chỉ ra 1 bài học nghiệp vụ, ví dụ: "phải làm sạch dữ liệu và kiểm tra tính toàn vẹn trước khi đưa ra nhận định".')
on conflict (set_id, position) do nothing;
insert into public.interview_questions (id, set_id, position, round_number, max_score, prompt, guidance, keywords, rubric, grading_rubric, reference_answer)
values ('075aa85f-a8ee-5ace-8374-80efac20c300', (select id from public.interview_sets where slug = 'r2w-supply-chain-20261019'), 4, 2, 30, 'Giải thích Hiệu ứng Bullwhip (Cái roi da) trong chuỗi cung ứng và đề xuất giải pháp cốt lõi để khắc phục?', '', '{}'::text[], '[{"id":"criterion_1","label":"Phân tích đúng nguyên nhân","weight":12,"maxScore":12},{"id":"criterion_2","label":"Giải pháp dựa trên Dữ liệu","weight":12,"maxScore":12},{"id":"criterion_3","label":"Từ vựng & Sự tự tin","weight":6,"maxScore":6}]'::jsonb, '[{"id":"criterion_1","label":"Phân tích đúng nguyên nhân","description":"- Tiêu chí 1 - Phân tích đúng nguyên nhân (12đ): Chỉ ra biến động nhu cầu ảo bị khuếch đại qua các tầng (Siêu thị  Đại lý  Nhà máy) do hoảng loạn ngắn hạn và thiếu chia sẻ thông tin.","keywords":[],"weight":12,"maxScore":12,"skill":"Phân tích đúng nguyên nhân"},{"id":"criterion_2","label":"Giải pháp dựa trên Dữ liệu","description":"- Tiêu chí 2 - Giải pháp dựa trên Dữ liệu (12đ): Đề xuất thu thập dữ liệu bán hàng thực tế tại điểm bán (POS Data) và chia sẻ tồn kho minh bạch toàn chuỗi (VMI/CPFR).","keywords":[],"weight":12,"maxScore":12,"skill":"Giải pháp dựa trên Dữ liệu"},{"id":"criterion_3","label":"Từ vựng & Sự tự tin","description":"- Tiêu chí 3 - Từ vựng & Sự tự tin (6đ): Dùng đúng thuật ngữ: Bullwhip Effect, Panic Buying, Point of Sale (POS) Data, VMI, CPFR.","keywords":[],"weight":6,"maxScore":6,"skill":"Từ vựng & Sự tự tin"}]'::jsonb, '- Tiêu chí 1 - Phân tích đúng nguyên nhân (12đ): Chỉ ra biến động nhu cầu ảo bị khuếch đại qua các tầng (Siêu thị  Đại lý  Nhà máy) do hoảng loạn ngắn hạn và thiếu chia sẻ thông tin.
- Tiêu chí 2 - Giải pháp dựa trên Dữ liệu (12đ): Đề xuất thu thập dữ liệu bán hàng thực tế tại điểm bán (POS Data) và chia sẻ tồn kho minh bạch toàn chuỗi (VMI/CPFR).
- Tiêu chí 3 - Từ vựng & Sự tự tin (6đ): Dùng đúng thuật ngữ: Bullwhip Effect, Panic Buying, Point of Sale (POS) Data, VMI, CPFR.')
on conflict (set_id, position) do nothing;
insert into public.interview_questions (id, set_id, position, round_number, max_score, prompt, guidance, keywords, rubric, grading_rubric, reference_answer)
values ('6eff508d-cee5-5210-8a19-9d28193e7cc3', (select id from public.interview_sets where slug = 'r2w-supply-chain-20261019'), 5, 2, 35, 'Các nhóm chỉ số quan trọng thường dùng để phân tích hiệu suất tồn kho và nhà cung cấp là gì?', '', '{}'::text[], '[{"id":"criterion_1","label":"Liệt kê đủ nhóm chỉ số","weight":18,"maxScore":18},{"id":"criterion_2","label":"Giải thích ý nghĩa nghiệp vụ","weight":10,"maxScore":10},{"id":"criterion_3","label":"Từ vựng & Sự tự tin","weight":7,"maxScore":7}]'::jsonb, '[{"id":"criterion_1","label":"Liệt kê đủ nhóm chỉ số","description":"- Tiêu chí 1 - Liệt kê đủ nhóm chỉ số (18đ): Số ngày tồn kho (DOI), Điểm đặt hàng lại (ROP), Tồn an toàn (Safety Stock), Tỷ lệ giao đúng hạn đủ lượng (OTIF), Lead Time.","keywords":[],"weight":18,"maxScore":18,"skill":"Liệt kê đủ nhóm chỉ số"},{"id":"criterion_2","label":"Giải thích ý nghĩa nghiệp vụ","description":"- Tiêu chí 2 - Giải thích ý nghĩa nghiệp vụ (10đ): Giải thích DOI cao gây ứ đọng vốn, OTIF thấp cảnh báo nguy cơ đứt gãy cung ứng; nêu được mối quan hệ giữa Lead Time và ROP.","keywords":[],"weight":10,"maxScore":10,"skill":"Giải thích ý nghĩa nghiệp vụ"},{"id":"criterion_3","label":"Từ vựng & Sự tự tin","description":"- Tiêu chí 3 - Từ vựng & Sự tự tin (7đ): Dùng đúng thuật ngữ: Days of Inventory (DOI), Reorder Point (ROP), OTIF, Lead Time, Working Capital.","keywords":[],"weight":7,"maxScore":7,"skill":"Từ vựng & Sự tự tin"}]'::jsonb, '- Tiêu chí 1 - Liệt kê đủ nhóm chỉ số (18đ): Số ngày tồn kho (DOI), Điểm đặt hàng lại (ROP), Tồn an toàn (Safety Stock), Tỷ lệ giao đúng hạn đủ lượng (OTIF), Lead Time.
- Tiêu chí 2 - Giải thích ý nghĩa nghiệp vụ (10đ): Giải thích DOI cao gây ứ đọng vốn, OTIF thấp cảnh báo nguy cơ đứt gãy cung ứng; nêu được mối quan hệ giữa Lead Time và ROP.
- Tiêu chí 3 - Từ vựng & Sự tự tin (7đ): Dùng đúng thuật ngữ: Days of Inventory (DOI), Reorder Point (ROP), OTIF, Lead Time, Working Capital.')
on conflict (set_id, position) do nothing;
insert into public.interview_questions (id, set_id, position, round_number, max_score, prompt, guidance, keywords, rubric, grading_rubric, reference_answer)
values ('24ed6060-1f3c-5818-bfc8-13a9d1e1b027', (select id from public.interview_sets where slug = 'r2w-supply-chain-20261019'), 6, 2, 35, 'Khi phát hiện chỉ số DOI của một SKU tăng vọt lên 90 ngày (gấp 6 lần định mức 14 ngày), bạn phân tích nguyên nhân và đề xuất xử lý thế nào?', '', '{}'::text[], '[{"id":"criterion_1","label":"Chẩn đoán nguyên nhân gốc rễ","weight":15,"maxScore":15},{"id":"criterion_2","label":"Đề xuất giải pháp hành động","weight":12,"maxScore":12},{"id":"criterion_3","label":"Từ vựng & Sự tự tin","weight":8,"maxScore":8}]'::jsonb, '[{"id":"criterion_1","label":"Chẩn đoán nguyên nhân gốc rễ","description":"- Tiêu chí 1 - Chẩn đoán nguyên nhân gốc rễ (15đ): Đối soát dữ liệu ROP, lịch sử đặt hàng, sai lệch dự báo (Over-forecasting) và xu hướng sụt giảm sức mua thực tế.","keywords":[],"weight":15,"maxScore":15,"skill":"Chẩn đoán nguyên nhân gốc rễ"},{"id":"criterion_2","label":"Đề xuất giải pháp hành động","description":"- Tiêu chí 2 - Đề xuất giải pháp hành động (12đ): Lập tức tạm ngưng đặt mua mới  Đề xuất chương trình bán kèm (Bundling), khuyến mãi kích cầu hoặc điều chuyển hàng nội bộ để giải phóng kho.","keywords":[],"weight":12,"maxScore":12,"skill":"Đề xuất giải pháp hành động"},{"id":"criterion_3","label":"Từ vựng & Sự tự tin","description":"- Tiêu chí 3 - Từ vựng & Sự tự tin (8đ): Dùng đúng thuật ngữ: Excess Stock, Over-forecasting, Bundling, Inventory Transfer, Root Cause Analysis.","keywords":[],"weight":8,"maxScore":8,"skill":"Từ vựng & Sự tự tin"}]'::jsonb, '- Tiêu chí 1 - Chẩn đoán nguyên nhân gốc rễ (15đ): Đối soát dữ liệu ROP, lịch sử đặt hàng, sai lệch dự báo (Over-forecasting) và xu hướng sụt giảm sức mua thực tế.
- Tiêu chí 2 - Đề xuất giải pháp hành động (12đ): Lập tức tạm ngưng đặt mua mới  Đề xuất chương trình bán kèm (Bundling), khuyến mãi kích cầu hoặc điều chuyển hàng nội bộ để giải phóng kho.
- Tiêu chí 3 - Từ vựng & Sự tự tin (8đ): Dùng đúng thuật ngữ: Excess Stock, Over-forecasting, Bundling, Inventory Transfer, Root Cause Analysis.')
on conflict (set_id, position) do nothing;
insert into public.interview_questions (id, set_id, position, round_number, max_score, prompt, guidance, keywords, rubric, grading_rubric, reference_answer)
values ('02a8b600-c9f0-5412-a8c4-a8a612eba0d5', (select id from public.interview_sets where slug = 'r2w-supply-chain-20261019'), 7, 3, 50, 'Chi phí Logistics tháng này tăng vọt 40%. Sếp yêu cầu bạn giải thích nhanh bằng lời (Data Storytelling) mà không đọc file Excel 1.000 dòng, bạn trình bày thế nào?', '', '{}'::text[], '[{"id":"criterion_1","label":"Ngôn ngữ Kinh doanh đơn giản","weight":20,"maxScore":20},{"id":"criterion_2","label":"Tìm đúng nguyên nhân có con số","weight":20,"maxScore":20},{"id":"criterion_3","label":"Từ vựng & Sự tự tin","weight":10,"maxScore":10}]'::jsonb, '[{"id":"criterion_1","label":"Ngôn ngữ Kinh doanh đơn giản","description":"- Tiêu chí 1 - Ngôn ngữ Kinh doanh đơn giản (20đ): Tuyệt đối không dùng thuật ngữ kỹ thuật rườm rà (Outliers, MAPE); dùng ngôn ngữ tài chính/kinh doanh (Doanh số, Tồn kho, Phí lưu bãi).","keywords":[],"weight":20,"maxScore":20,"skill":"Ngôn ngữ Kinh doanh đơn giản"},{"id":"criterion_2","label":"Tìm đúng nguyên nhân có con số","description":"- Tiêu chí 2 - Tìm đúng nguyên nhân có con số (20đ): Giải thích logic: Sales dự báo vượt thực tế làm hàng phơi kho ngoài  phát sinh 40% chi phí lưu kho.","keywords":[],"weight":20,"maxScore":20,"skill":"Tìm đúng nguyên nhân có con số"},{"id":"criterion_3","label":"Từ vựng & Sự tự tin","description":"- Tiêu chí 3 - Từ vựng & Sự tự tin (10đ): Dùng đúng thuật ngữ: Data Storytelling, Storage Cost, Forecast Error, Executive Summary.","keywords":[],"weight":10,"maxScore":10,"skill":"Từ vựng & Sự tự tin"}]'::jsonb, '- Tiêu chí 1 - Ngôn ngữ Kinh doanh đơn giản (20đ): Tuyệt đối không dùng thuật ngữ kỹ thuật rườm rà (Outliers, MAPE); dùng ngôn ngữ tài chính/kinh doanh (Doanh số, Tồn kho, Phí lưu bãi).
- Tiêu chí 2 - Tìm đúng nguyên nhân có con số (20đ): Giải thích logic: Sales dự báo vượt thực tế làm hàng phơi kho ngoài  phát sinh 40% chi phí lưu kho.
- Tiêu chí 3 - Từ vựng & Sự tự tin (10đ): Dùng đúng thuật ngữ: Data Storytelling, Storage Cost, Forecast Error, Executive Summary.')
on conflict (set_id, position) do nothing;
insert into public.interview_questions (id, set_id, position, round_number, max_score, prompt, guidance, keywords, rubric, grading_rubric, reference_answer)
values ('470c7947-0a7c-5153-bef3-f7dbfa2f69e5', (select id from public.interview_sets where slug = 'r2w-supply-chain-20261019'), 8, 3, 50, 'Dữ liệu trích xuất từ hệ thống ERP bị thiếu hụt thông tin Lead Time của một số nhà cung cấp, bạn làm gì trước khi đưa ra báo cáo phân tích?', '', '{}'::text[], '[{"id":"criterion_1","label":"Bảo toàn tính toàn vẹn dữ liệu","weight":20,"maxScore":20},{"id":"criterion_2","label":"Minh bạch giả định & Cảnh báo","weight":20,"maxScore":20},{"id":"criterion_3","label":"Từ vựng & Sự tự tin","weight":10,"maxScore":10}]'::jsonb, '[{"id":"criterion_1","label":"Bảo toàn tính toàn vẹn dữ liệu","description":"- Tiêu chí 1 - Bảo toàn tính toàn vẹn dữ liệu (20đ): Tuyệt đối không tự bịa số liệu; tiến hành đối soát chéo với Bộ phận Thu mua/Kho để làm sạch dữ liệu.","keywords":[],"weight":20,"maxScore":20,"skill":"Bảo toàn tính toàn vẹn dữ liệu"},{"id":"criterion_2","label":"Minh bạch giả định & Cảnh báo","description":"- Tiêu chí 2 - Minh bạch giả định & Cảnh báo (20đ): Đánh dấu rõ vùng dữ liệu chưa chắc chắn, ghi chú giả định (Assumptions) và nêu rõ mức độ ảnh hưởng đến kết quả phân tích.","keywords":[],"weight":20,"maxScore":20,"skill":"Minh bạch giả định & Cảnh báo"},{"id":"criterion_3","label":"Từ vựng & Sự tự tin","description":"- Tiêu chí 3 - Từ vựng & Sự tự tin (10đ): Dùng đúng thuật ngữ: Data Cleaning, Data Integrity, Cross-validation, Assumptions.","keywords":[],"weight":10,"maxScore":10,"skill":"Từ vựng & Sự tự tin"}]'::jsonb, '- Tiêu chí 1 - Bảo toàn tính toàn vẹn dữ liệu (20đ): Tuyệt đối không tự bịa số liệu; tiến hành đối soát chéo với Bộ phận Thu mua/Kho để làm sạch dữ liệu.
- Tiêu chí 2 - Minh bạch giả định & Cảnh báo (20đ): Đánh dấu rõ vùng dữ liệu chưa chắc chắn, ghi chú giả định (Assumptions) và nêu rõ mức độ ảnh hưởng đến kết quả phân tích.
- Tiêu chí 3 - Từ vựng & Sự tự tin (10đ): Dùng đúng thuật ngữ: Data Cleaning, Data Integrity, Cross-validation, Assumptions.')
on conflict (set_id, position) do nothing;
insert into public.interview_questions (id, set_id, position, round_number, max_score, prompt, guidance, keywords, rubric, grading_rubric, reference_answer)
values ('e0140cbf-f8ed-5134-88dc-dc4120512fe1', (select id from public.interview_sets where slug = 'r2w-tro-ly-thue-20261019'), 1, 1, 30, 'Hãy giới thiệu ngắn gọn về bản thân và lý do bạn lựa chọn theo đuổi công việc Trợ lý thuế?', '', '{}'::text[], '[{"id":"criterion_1","label":"Giới thiệu đúng trọng tâm","weight":14,"maxScore":14},{"id":"criterion_2","label":"Lý do chọn thuế","weight":11,"maxScore":11},{"id":"criterion_3","label":"Trình bày","weight":5,"maxScore":5}]'::jsonb, '[{"id":"criterion_1","label":"Giới thiệu đúng trọng tâm","description":"Tiêu chí 1 - Giới thiệu đúng trọng tâm (14đ): Nêu ngành học, kinh nghiệm/thực tập hoặc hoạt động liên quan.","keywords":[],"weight":14,"maxScore":14,"skill":"Giới thiệu đúng trọng tâm"},{"id":"criterion_2","label":"Lý do chọn thuế","description":"Tiêu chí 2 - Lý do chọn thuế (11đ): Nêu được lý do cụ thể như quan tâm chính sách thuế, thích số liệu và quy định","keywords":[],"weight":11,"maxScore":11,"skill":"Lý do chọn thuế"},{"id":"criterion_3","label":"Trình bày","description":"Tiêu chí 3 - Trình bày (5đ): Rõ ràng, có cấu trúc, không lan man.","keywords":[],"weight":5,"maxScore":5,"skill":"Trình bày"}]'::jsonb, 'Tiêu chí 1 - Giới thiệu đúng trọng tâm (14đ): Nêu ngành học, kinh nghiệm/thực tập hoặc hoạt động liên quan.
Tiêu chí 2 - Lý do chọn thuế (11đ): Nêu được lý do cụ thể như quan tâm chính sách thuế, thích số liệu và quy định
Tiêu chí 3 - Trình bày (5đ): Rõ ràng, có cấu trúc, không lan man.')
on conflict (set_id, position) do nothing;
insert into public.interview_questions (id, set_id, position, round_number, max_score, prompt, guidance, keywords, rubric, grading_rubric, reference_answer)
values ('6f701dff-9a96-54ff-878c-ea7d0b430002', (select id from public.interview_sets where slug = 'r2w-tro-ly-thue-20261019'), 2, 1, 35, 'Theo bạn, trợ lý thuế cần có những kỹ năng quan trọng nào?', '', '{}'::text[], '[{"id":"criterion_1","label":"Kiến thức thuế cơ bản","weight":20,"maxScore":20},{"id":"criterion_2","label":"Kiểm tra chứng từ","weight":10,"maxScore":10},{"id":"criterion_3","label":"Cập nhật quy định","weight":5,"maxScore":5}]'::jsonb, '[{"id":"criterion_1","label":"Kiến thức thuế cơ bản","description":"Tiêu chí 1 - Kiến thức thuế cơ bản (20đ): Hiểu sự cần thiết của kiến thức về các sắc thuế và quy định liên quan.","keywords":[],"weight":20,"maxScore":20,"skill":"Kiến thức thuế cơ bản"},{"id":"criterion_2","label":"Kiểm tra chứng từ","description":"Tiêu chí 2 - Kiểm tra chứng từ (10đ): Biết kiểm tra hóa đơn, chứng từ và đối chiếu số liệu.","keywords":[],"weight":10,"maxScore":10,"skill":"Kiểm tra chứng từ"},{"id":"criterion_3","label":"Cập nhật quy định","description":"Tiêu chí 3 - Cập nhật quy định (5đ): Nhận thức chính sách thuế có thể thay đổi.","keywords":[],"weight":5,"maxScore":5,"skill":"Cập nhật quy định"}]'::jsonb, 'Tiêu chí 1 - Kiến thức thuế cơ bản (20đ): Hiểu sự cần thiết của kiến thức về các sắc thuế và quy định liên quan.
Tiêu chí 2 - Kiểm tra chứng từ (10đ): Biết kiểm tra hóa đơn, chứng từ và đối chiếu số liệu.
Tiêu chí 3 - Cập nhật quy định (5đ): Nhận thức chính sách thuế có thể thay đổi.')
on conflict (set_id, position) do nothing;
insert into public.interview_questions (id, set_id, position, round_number, max_score, prompt, guidance, keywords, rubric, grading_rubric, reference_answer)
values ('bed94dde-5c8a-5212-b5f7-eb6ea7c21e62', (select id from public.interview_sets where slug = 'r2w-tro-ly-thue-20261019'), 3, 1, 35, 'Vì sao việc cập nhật các quy định thuế lại quan trọng đối với một trợ lý thuế?', '', '{}'::text[], '[{"id":"criterion_1","label":"Nhận thức về thay đổi chính sách","weight":18,"maxScore":18},{"id":"criterion_2","label":"Ảnh hưởng đến công việc","weight":10,"maxScore":10},{"id":"criterion_3","label":"Chủ động cập nhật","weight":7,"maxScore":7}]'::jsonb, '[{"id":"criterion_1","label":"Nhận thức về thay đổi chính sách","description":"Tiêu chí 1 - Nhận thức về thay đổi chính sách (18đ): Hiểu quy định thuế có thể được cập nhật/thay đổi.","keywords":[],"weight":18,"maxScore":18,"skill":"Nhận thức về thay đổi chính sách"},{"id":"criterion_2","label":"Ảnh hưởng đến công việc","description":"Tiêu chí 2 - Ảnh hưởng đến công việc (10đ): Biết thay đổi chính sách có thể ảnh hưởng đến cách kê khai và xử lý hồ sơ","keywords":[],"weight":10,"maxScore":10,"skill":"Ảnh hưởng đến công việc"},{"id":"criterion_3","label":"Chủ động cập nhật","description":"Tiêu chí 3 - Chủ động cập nhật (7đ): Nêu được cách cập nhật từ nguồn chính thống, tài liệu chuyên môn hoặc hướng dẫn của doanh nghiệp.","keywords":[],"weight":7,"maxScore":7,"skill":"Chủ động cập nhật"}]'::jsonb, 'Tiêu chí 1 - Nhận thức về thay đổi chính sách (18đ): Hiểu quy định thuế có thể được cập nhật/thay đổi.
Tiêu chí 2 - Ảnh hưởng đến công việc (10đ): Biết thay đổi chính sách có thể ảnh hưởng đến cách kê khai và xử lý hồ sơ
Tiêu chí 3 - Chủ động cập nhật (7đ): Nêu được cách cập nhật từ nguồn chính thống, tài liệu chuyên môn hoặc hướng dẫn của doanh nghiệp.')
