insert into public.interview_questions (id, set_id, position, round_number, max_score, prompt, guidance, keywords, rubric, grading_rubric, reference_answer)
values ('cc24253e-8548-5e1c-a522-fa2b6362c684', (select id from public.interview_sets where slug = 'r2w-tro-ly-thue-20261019'), 4, 2, 35, 'Khi kiểm tra hồ sơ thuế của doanh nghiệp, bạn sẽ kiểm tra hóa đơn và đối chiếu chứng từ như thế nào để đảm bảo tính chính xác trước khi kê khai thuế?', '', '{}'::text[], '[{"id":"criterion_1","label":"Kiểm tra hóa đơn","weight":20,"maxScore":20},{"id":"criterion_2","label":"Đối chiếu chứng từ","weight":10,"maxScore":10},{"id":"criterion_3","label":"Xử lý trước khi kê khai","weight":5,"maxScore":5}]'::jsonb, '[{"id":"criterion_1","label":"Kiểm tra hóa đơn","description":"Tiêu chí 1 - Kiểm tra hóa đơn (20đ): Kiểm tra tên, mã số thuế, số tiền, thuế suất, ngày và nội dung.","keywords":[],"weight":20,"maxScore":20,"skill":"Kiểm tra hóa đơn"},{"id":"criterion_2","label":"Đối chiếu chứng từ","description":"Tiêu chí 2 - Đối chiếu chứng từ (10đ): So sánh với hợp đồng, phiếu nhập/xuất, biên bản giao nhận và sổ kế toán.","keywords":[],"weight":10,"maxScore":10,"skill":"Đối chiếu chứng từ"},{"id":"criterion_3","label":"Xử lý trước khi kê khai","description":"Tiêu chí 3 - Xử lý trước khi kê khai (5đ): Trao đổi với người phụ trách/khách hàng và xử lý theo quy định.","keywords":[],"weight":5,"maxScore":5,"skill":"Xử lý trước khi kê khai"}]'::jsonb, 'Tiêu chí 1 - Kiểm tra hóa đơn (20đ): Kiểm tra tên, mã số thuế, số tiền, thuế suất, ngày và nội dung.
Tiêu chí 2 - Đối chiếu chứng từ (10đ): So sánh với hợp đồng, phiếu nhập/xuất, biên bản giao nhận và sổ kế toán.
Tiêu chí 3 - Xử lý trước khi kê khai (5đ): Trao đổi với người phụ trách/khách hàng và xử lý theo quy định.')
