insert into public.interview_questions (id, set_id, position, round_number, max_score, prompt, guidance, keywords, rubric, grading_rubric, reference_answer)
values ('436da2b2-76c1-5a81-a336-5eeac26e8333', (select id from public.interview_sets where slug = 'r2w-tro-ly-thue-20261019'), 5, 2, 30, 'Nếu số liệu trên sổ kế toán không khớp với số liệu dùng để kê khai thuế, bạn sẽ làm gì?', '', '{}'::text[], '[{"id":"criterion_1","label":"Đối chiếu số liệu","weight":15,"maxScore":15},{"id":"criterion_2","label":"Xác định nguyên nhân","weight":10,"maxScore":10},{"id":"criterion_3","label":"Báo cáo và xử lý","weight":5,"maxScore":5}]'::jsonb, '[{"id":"criterion_1","label":"Đối chiếu số liệu","description":"Tiêu chí 1 - Đối chiếu số liệu (15đ): So sánh sổ kế toán, hóa đơn, bảng kê và hồ sơ khai thuế.","keywords":[],"weight":15,"maxScore":15,"skill":"Đối chiếu số liệu"},{"id":"criterion_2","label":"Xác định nguyên nhân","description":"Tiêu chí 2 - Xác định nguyên nhân (10đ): Kiểm tra lỗi nhập liệu, thiếu hóa đơn, sai kỳ hoặc xử lý chưa phù hợp.","keywords":[],"weight":10,"maxScore":10,"skill":"Xác định nguyên nhân"},{"id":"criterion_3","label":"Báo cáo và xử lý","description":"Tiêu chí 3 - Báo cáo và xử lý (5đ): Trao đổi với người phụ trách và thực hiện điều chỉnh/bổ sung nếu cần.","keywords":[],"weight":5,"maxScore":5,"skill":"Báo cáo và xử lý"}]'::jsonb, 'Tiêu chí 1 - Đối chiếu số liệu (15đ): So sánh sổ kế toán, hóa đơn, bảng kê và hồ sơ khai thuế.
Tiêu chí 2 - Xác định nguyên nhân (10đ): Kiểm tra lỗi nhập liệu, thiếu hóa đơn, sai kỳ hoặc xử lý chưa phù hợp.
Tiêu chí 3 - Báo cáo và xử lý (5đ): Trao đổi với người phụ trách và thực hiện điều chỉnh/bổ sung nếu cần.')
on conflict (set_id, position) do nothing;
insert into public.interview_questions (id, set_id, position, round_number, max_score, prompt, guidance, keywords, rubric, grading_rubric, reference_answer)
values ('0f41d4a6-d2ba-5664-8fc4-1f8c698e8816', (select id from public.interview_sets where slug = 'r2w-tro-ly-thue-20261019'), 6, 2, 35, 'Khi kiểm tra hồ sơ thuế, bạn phát hiện số liệu doanh thu giữa hóa đơn và bảng tổng hợp không khớp. Bạn sẽ kiểm tra những gì?', '', '{}'::text[], '[{"id":"criterion_1","label":"Kiểm tra hóa đơn","weight":18,"maxScore":18},{"id":"criterion_2","label":"Đối chiếu bảng tổng hợp","weight":10,"maxScore":10},{"id":"criterion_3","label":"Xử lý chênh lệch","weight":7,"maxScore":7}]'::jsonb, '[{"id":"criterion_1","label":"Kiểm tra hóa đơn","description":"Tiêu chí 1 – Kiểm tra hóa đơn (18đ): Đối chiếu số lượng hóa đơn, số hóa đơn, ngày lập, giá trị trước thuế, thuế GTGT và tổng giá trị hóa đơn.","keywords":[],"weight":18,"maxScore":18,"skill":"Kiểm tra hóa đơn"},{"id":"criterion_2","label":"Đối chiếu bảng tổng hợp","description":"Tiêu chí 2 – Đối chiếu bảng tổng hợp (10đ): Kiểm tra dữ liệu nhập liệu, công thức tính toán, các hóa đơn bị thiếu hoặc trùng và tính đầy đủ, chính xác của số liệu tổng hợp.","keywords":[],"weight":10,"maxScore":10,"skill":"Đối chiếu bảng tổng hợp"},{"id":"criterion_3","label":"Xử lý chênh lệch","description":"Tiêu chí 3 – Xử lý chênh lệch (7đ): Xác định nguyên nhân sai lệch, đối chiếu với chứng từ liên quan, báo cáo người phụ trách và đề xuất điều chỉnh theo quy định trước khi kê khai thuế.","keywords":[],"weight":7,"maxScore":7,"skill":"Xử lý chênh lệch"}]'::jsonb, 'Tiêu chí 1 – Kiểm tra hóa đơn (18đ): Đối chiếu số lượng hóa đơn, số hóa đơn, ngày lập, giá trị trước thuế, thuế GTGT và tổng giá trị hóa đơn.
Tiêu chí 2 – Đối chiếu bảng tổng hợp (10đ): Kiểm tra dữ liệu nhập liệu, công thức tính toán, các hóa đơn bị thiếu hoặc trùng và tính đầy đủ, chính xác của số liệu tổng hợp.
Tiêu chí 3 – Xử lý chênh lệch (7đ): Xác định nguyên nhân sai lệch, đối chiếu với chứng từ liên quan, báo cáo người phụ trách và đề xuất điều chỉnh theo quy định trước khi kê khai thuế.')
on conflict (set_id, position) do nothing;
insert into public.interview_questions (id, set_id, position, round_number, max_score, prompt, guidance, keywords, rubric, grading_rubric, reference_answer)
values ('944b30e5-39a7-54bc-aad4-8424a3b8e843', (select id from public.interview_sets where slug = 'r2w-tro-ly-thue-20261019'), 7, 3, 50, 'Gần đến hạn nộp hồ sơ thuế nhưng khách hàng chưa cung cấp đầy đủ chứng từ. Bạn sẽ xử lý như thế nào?', '', '{}'::text[], '[{"id":"criterion_1","label":"Xác định chứng từ thiếu","weight":20,"maxScore":20},{"id":"criterion_2","label":"Chủ động liên hệ","weight":20,"maxScore":20},{"id":"criterion_3","label":"Không tự ý kê khai","weight":10,"maxScore":10}]'::jsonb, '[{"id":"criterion_1","label":"Xác định chứng từ thiếu","description":"Tiêu chí 1 - Xác định chứng từ thiếu (20đ): Lập danh sách hóa đơn, chứng từ hoặc thông tin còn thiếu.","keywords":[],"weight":20,"maxScore":20,"skill":"Xác định chứng từ thiếu"},{"id":"criterion_2","label":"Chủ động liên hệ","description":"Tiêu chí 2 - Chủ động liên hệ (20đ): Nhắc khách hàng về tài liệu và thời hạn cần cung cấp.","keywords":[],"weight":20,"maxScore":20,"skill":"Chủ động liên hệ"},{"id":"criterion_3","label":"Không tự ý kê khai","description":"Tiêu chí 3 - Không tự ý kê khai (10đ): Không tự tạo số liệu hoặc kê khai khi chưa có đủ cơ sở.","keywords":[],"weight":10,"maxScore":10,"skill":"Không tự ý kê khai"}]'::jsonb, 'Tiêu chí 1 - Xác định chứng từ thiếu (20đ): Lập danh sách hóa đơn, chứng từ hoặc thông tin còn thiếu.
Tiêu chí 2 - Chủ động liên hệ (20đ): Nhắc khách hàng về tài liệu và thời hạn cần cung cấp.
Tiêu chí 3 - Không tự ý kê khai (10đ): Không tự tạo số liệu hoặc kê khai khi chưa có đủ cơ sở.')
on conflict (set_id, position) do nothing;
insert into public.interview_questions (id, set_id, position, round_number, max_score, prompt, guidance, keywords, rubric, grading_rubric, reference_answer)
values ('27045a52-ea6c-5031-b38b-1856cb4806ab', (select id from public.interview_sets where slug = 'r2w-tro-ly-thue-20261019'), 8, 3, 50, 'Khách hàng yêu cầu bạn đưa một khoản chi phí vào hồ sơ thuế nhưng chứng từ cung cấp chưa đủ để xác định khoản chi phí đó có phù hợp hay không. Bạn sẽ làm gì?', '', '{}'::text[], '[{"id":"criterion_1","label":"Kiểm tra chứng từ","weight":20,"maxScore":20},{"id":"criterion_2","label":"Yêu cầu bổ sung","weight":20,"maxScore":20},{"id":"criterion_3","label":"Trao đổi người phụ trách","weight":10,"maxScore":10}]'::jsonb, '[{"id":"criterion_1","label":"Kiểm tra chứng từ","description":"Tiêu chí 1 - Kiểm tra chứng từ (20đ): Kiểm tra hóa đơn và các tài liệu liên quan.","keywords":[],"weight":20,"maxScore":20,"skill":"Kiểm tra chứng từ"},{"id":"criterion_2","label":"Yêu cầu bổ sung","description":"Tiêu chí 2 - Yêu cầu bổ sung (20đ): Chủ động yêu cầu khách hàng cung cấp tài liệu còn thiếu.","keywords":[],"weight":20,"maxScore":20,"skill":"Yêu cầu bổ sung"},{"id":"criterion_3","label":"Trao đổi người phụ trách","description":"Tiêu chí 3 - Trao đổi người phụ trách (10đ): Báo cáo nếu chưa thể xác định cách xử lý.","keywords":[],"weight":10,"maxScore":10,"skill":"Trao đổi người phụ trách"}]'::jsonb, 'Tiêu chí 1 - Kiểm tra chứng từ (20đ): Kiểm tra hóa đơn và các tài liệu liên quan.
Tiêu chí 2 - Yêu cầu bổ sung (20đ): Chủ động yêu cầu khách hàng cung cấp tài liệu còn thiếu.
Tiêu chí 3 - Trao đổi người phụ trách (10đ): Báo cáo nếu chưa thể xác định cách xử lý.')
on conflict (set_id, position) do nothing;
